__vfs['configs/app/lang/fa.lua'] = function(...)
--[[
  configs/lang/fa.lua — فارسی (Persian/Farsi)

  Flat table of dotted keys -> strings, loaded by core/utils/lang.lua.
  Looked up at runtime via the global T(key, ...) function, e.g.:
      T("common.ok")                          -> "تأیید"
      T("settings.window_width_desc", 400, 650) -> "عرض منوی شناور (400 - 650 dp)"

  Conventions:
    - Keys are namespaced by file: "settings.*", "account.*", "cups.*", etc.
    - %s / %d / %X etc. are string.format placeholders — keep them in the
      same order when translating, but they don't need to keep the same
      letter (e.g. %s can become %d if the translated grammar needs it).
    - Entries that are Lua arrays (e.g. spinner option lists) are returned
      as-is, untouched by string.format.
    - LOG.*() calls, debug tags, and internal cache/state keys are NOT
      translated — only user-visible text (dialogs, toasts, buttons,
      module titles/descriptions) lives here.

  This file handles the Persian localization for the VOID script.
]]

return {

-- ── Common / shared (buttons, generic dialog text) ───────────────────────────
["common.ok"] = "تأیید",
["common.cancel"] = "لغو",
["common.yes"] = "بله",
["common.no"] = "خیر",
["common.failed"] = "ناموفق",
["common.success"] = "موفق",
["common.later"] = "بعداً",
["common.got_it"] = "متوجه شدم",
["common.retry"] = "تلاش مجدد",
["common.wait_safe"] = "صبر کنید (امن)",
["common.waiting"] = "در حال انتظار...",
["common.force_exit"] = "خروج اجباری",
["common.proceed_anyway"] = "به هر حال ادامه بده",
["common.manual_mode"] = "حالت دستی",
["common.update_button"] = "به‌روزرسانی",
["common.launch_failed"] = "اجرا ناموفق",
["common.confirm_exit_title"] = "تأیید خروج",
["common.confirm_exit_msg"] = "از اسکریپت خارج می‌شوید؟",
