        raw = enum.byName and enum.byName[value]
        if raw == nil then
            log(string.format("[set] collectWrite REJECTED at 0x%X offset=0x%X: unknown enum name '%s' in '%s'",
                baseAddress, field.offset, value, tostring(field.enum)))
            return false
        end
