__vfs['modules/tabs/account.lua'] = function(...)
--[[
  Account Tab - Player profile modifications
  Features: Change player name, Change GP, Fake unlock/VIP, Fake Rank

  UI wiring only. Memory ops live in modules/ops/account.lua.

  @module callback Receives container View to populate with modules
]]

local ops = CrashHandler.loadFeature("modules/ops/account.lua")

return function(container)
    local function t(key, ...) return T("account." .. key, ...) end

    addModule(container, "change_name", t("change_name.title"), t("change_name.desc"), "input", {
        { hint = t("change_name.hint"), value = "", type = "text" }
    }, function(done, val)
        ops.changeName(val, function(status)
            if status == "empty" then
                showToast(t("change_name.empty"))
            elseif status == "too_long" then
                showDialog(t("change_name.too_long_title"), t("change_name.too_long_msg"), T("common.ok"))
            elseif status == "resolve_failed" then
                showToast(t("change_name.resolve_failed"))
            else
                showToast(t("change_name.applied", val))
            end
        end)
        done()
    end)

    addModule(container, "change_gp", t("change_gp.title"), t("change_gp.desc"), "input", {
        { hint = t("change_gp.hint"), value = "8", type = "number" }
    }, function(done, val)
        ops.changeGp(val, function(status)
            if status == "max_int" then
                showDialog(t("change_gp.max_int_title"), t("change_gp.lower_value"), {T("common.ok")})
            elseif status == "too_low" then
                showDialog(t("change_gp.too_low_title"), t("change_gp.higher_value"), {T("common.ok")})
            else
                showToast(t("change_gp.applied", tostring(val)))
            end
        end)
        done()
    end)

    addModule(container, "change_ws", t("change_ws.title"), t("change_ws.desc"), "button", nil,
    function(done)
        local result = showPrompt(t("change_ws.title"), {
            { t("change_ws.prompt_best"),    "number", "1" },
            { t("change_ws.prompt_current"), "number", "1" },
        })
        if not result then done() return end

        local best    = math.floor(tonumber(result[1]) or 1)
        local current = math.floor(tonumber(result[2]) or 1)

        best    = math.max(0, math.min(2147483647, best))
        current = math.max(0, math.min(2147483647, current))

        if current > best then
            showDialog(
                t("change_ws.current_over_best_title"),
                t("change_ws.current_over_best_msg"),
                T("common.ok")
            )
            done(); return
        end

        ops.changeWinStreak(current, best, function(status)
            if status == "resolve_failed" then
                showToast(t("change_ws.resolve_failed"), true)
            else
                showToast(t("change_ws.applied", tostring(current), tostring(best)))
            end
        end)
        done()
    end)

    addArchModule(container, "fake_unlock", t("fake_unlock.title"), t("fake_unlock.desc"), "switch", nil, aobs.fakeUnlock)

    addArchModule(container, "fake_vip", t("fake_vip.title"), t("fake_vip.desc"), "switch", nil, aobs.fakeVip)

    addModule(container, "ad_free", t("ad_free.title"), t("ad_free.desc"), "switch", nil, function(done, state)
        ops.setAdFree(state, function(status)
            showToast(t("ad_free." .. status), true)
        end)
        done()
    end)

    addModule(container, "fake_rank", t("fake_rank.title"), t("fake_rank.desc"), "input", {
        { hint = t("fake_rank.hint"), value = "50.0", type = "number" }
    }, function(done, val)
        if not ops.isCupsTab() then
            LOG.warn("FakeRank", "Not in Cups tab.")
            showToast(t("fake_rank.not_in_cups"))
            done()
            return
        end

        local confirm = showDialog(
            t("fake_rank.race_warn_title"),
            t("fake_rank.race_warn_msg"),
            {t("fake_rank.continue_button")},
            {T("common.cancel")}
        )

        if confirm ~= 1 then
            done()
            return
        end

        ops.applyFakeRank(val, function()
            showToast(t("fake_rank.applied", tostring(val)))
        end)
        done()
    end)
end

end

__vfs['modules/tabs/adventure.lua'] = function(...)
--[[
  Adventure Tab - Adventure mode features
  Features: Auto adventure chests, Set distance (+ optional loop)

  UI wiring only. Memory ops live in modules/ops/adventure.lua.

  @module callback Receives container View to populate with modules
]]

local ops = CrashHandler.loadFeature("modules/ops/adventure.lua")

return function(container)
    local function t(key, ...) return T("adventure." .. key, ...) end

    addModule(container, "auto_adventure_chests", t("auto_adventure_chests.title"), t("auto_adventure_chests.desc"), "button", nil,
    function(done)
        ops.autoAdventureChests(function(status)
            if status == "none_found" then
                showToast(t("auto_adventure_chests.none_found"))
            else
                showToast(t("auto_adventure_chests.done"))
            end
        end)
        done()
    end)

    addModule(container, "free_adventure_shop", t("free_adventure_shop.title"), t("free_adventure_shop.desc"), "switch", nil,
    function(done, state)
        ops.freeAdventureShop(state, function(status)
            if status == "resolve_failed" then
                showToast(t("free_adventure_shop.resolve_failed"), true)
            elseif status == "reverted" then
                showToast(t("free_adventure_shop.reverted"))
            else
                showToast(t("free_adventure_shop.applied"))
            end
        end)
        done()
    end)

    addArchModule(container, "set_distance", t("set_distance.title"), t("set_distance.desc"), "button", nil,
    function(done)
        -- Loop already running? Offer to stop it.
        if ops.isLoopActive() then
            local action = showDialog(
                t("set_distance.loop_active_title"),
                t("set_distance.loop_active_msg"),
                {t("set_distance.stop_loop")}, {t("set_distance.keep_running")}
            )
            if action == 1 then
                ops.stopLoop()
                showToast(t("set_distance.loop_will_stop"))
            end
            done()
            return
        end

        local result = showPrompt(t("set_distance.title"), {
            {t("set_distance.prompt_target"), "number", "5000"},
            {t("set_distance.prompt_loop"),     "switch",  "false"},
            {t("set_distance.prompt_interval"), "number", "3500"},
        })

        if not result then
            done()
            return
        end

        local target_meters = tonumber(result[1]) or 5000
        local loop_enabled  = result[2] == "true"
        local loop_interval = math.max(250, tonumber(result[3]) or 1000)

        if loop_enabled then
            local warn = showDialog(
                t("set_distance.loop_warn_title"),
                t("set_distance.loop_warn_msg", tostring(loop_interval)),
                {t("set_distance.continue_button")},
                {T("common.cancel")}
            )
            if warn ~= 1 then
                done()
                return
            end
        end

        -- Warn if > 5000m — no stars, but race still counts distance
        if target_meters > 5000 then
            local warn = showDialog(
                t("set_distance.over_max_title"),
                t("set_distance.over_max_msg"),
                {t("set_distance.continue_button")}, {T("common.cancel")}
            )
            if warn ~= 1 then
                done()
                return
            end
        end

        ops.setDistance(
            { target_meters = target_meters, loop_enabled = loop_enabled, loop_interval = loop_interval },
            {
                onApply = function(status, phase)
                    if status == "not_in_adventure" then
                        showToast(t("set_distance.not_in_adventure"))
                    elseif status == "start_race_first" then
                        showToast(t("set_distance.start_race_first"))
                    elseif phase == "initial" then
                        showToast(t("set_distance.applied", tostring(target_meters)))
                    end
                end,
                onLoopRunning = function() showToast(t("set_distance.loop_running"), true) end,
                onLoopStopped = function() showToast(t("set_distance.loop_stopped")) end,
            }
        )
        done()
    end)
end

end

__vfs['modules/tabs/console.lua'] = function(...)
--[[
  Console Tab - Crash & log viewer (Script section)

  Reads the in-memory ring buffers from the global CrashHandler engine and
  renders them as a scrollable report list with Copy all / Refresh / Clear.
  This tab is excluded from ui.lua's view cache, so it re-renders on every open.

  @module callback Receives container View to populate with modules
]]

return function(container)
    local function t(key, ...) return T("console." .. key, ...) end

    if not CrashHandler then
        local tv = TextView(activity)
        tv.setText(t("unavailable"))
        tv.setTextColor(UI.SUB)
        container.addView(tv)
        return
    end

    -- ── Action button (shares row width equally) ──────────────────────────────
    local function makeButton(label, onTap)
        local btn = TextView(activity)
        local lp = LinLayoutParams(0, -2, 1.0)
        lp.rightMargin = dp(6)
        btn.setLayoutParams(lp)
        btn.setText(label)
        btn.setTextColor(UI.LOGO)
        btn.setGravity(Gravity.CENTER)
        btn.setTypeface(Typeface.create("sans-serif-medium", Typeface.BOLD))
        btn.setTextSize(1, 12)
        btn.setPadding(dp(10), dp(9), dp(10), dp(9))
        btn.setBackground(getSkin(UI.ACCENT, 8))
        btn.setOnClickListener(View.OnClickListener({ onClick = function() pcall(onTap) end }))
        return btn
    end

    -- ── Entry renderers ───────────────────────────────────────────────────────
    local function crashCard(e)
        local card = LinearLayout(activity)
        card.setOrientation(1)
        setLayoutDir(card)
        local lp = LinLayoutParams(-1, -2)
        lp.bottomMargin = dp(8)
        card.setLayoutParams(lp)
        card.setPadding(dp(12), dp(10), dp(12), dp(10))
        card.setBackground(getSkin(UI.CARD, 10, 1, UI.STROKE))

        local head = TextView(activity)
        head.setText(string.format("✖ [%s]  %s", e.ts, e.tag))
        head.setTextColor(UI.CONSOLE.CRASH)
        head.setTypeface(Typeface.create("sans-serif-medium", Typeface.BOLD))
        head.setTextSize(1, 12)
        card.addView(head)

        local msg = TextView(activity)
        msg.setText(tostring(e.message))
        msg.setTextColor(UI.TEXT)
        msg.setTextSize(1, 12)
        card.addView(msg)

        -- Tap for the full report (traceback included) with a Copy action.
        card.setClickable(true)
        card.setOnClickListener(View.OnClickListener({ onClick = function()
            local detail = string.format("%s\n\n%s", e.ts, tostring(e.message))
            if e.traceback then
                detail = detail .. "\n\n" .. tostring(e.traceback)
            end
            showDialog(t("details_title", e.tag), detail,
                { t("copy"), function()
                    pcall(function()
                        local cm = activity.getSystemService("clipboard")
                        cm.setPrimaryClip(ClipData.newPlainText("VOID Crash", detail))
                    end)
                    showToast(t("copied_one"))
                end },
                { T("common.ok") })
        end }))

        if e.traceback then
            local tb = TextView(activity)
            tb.setText(tostring(e.traceback))
            tb.setTextColor(UI.SUB)
            tb.setTextSize(1, 9)
            tb.setTypeface(Typeface.create("monospace", Typeface.NORMAL))
            local tlp = LinLayoutParams(-1, -2)
            tlp.topMargin = dp(4)
            tb.setLayoutParams(tlp)
            card.addView(tb)
        end

        return card
    end

    -- Level glyph + color, both driven by UI.CONSOLE (configs/app/colors.lua).
    local function levelStyle(level)
        if level == "ERROR" or level == "FATAL" then return "✖", UI.CONSOLE.ERROR
        elseif level == "WARN"                   then return "⚠", UI.CONSOLE.WARN
        elseif level == "DEBUG"                  then return "·", UI.CONSOLE.DEBUG
        else                                          return "ℹ", UI.CONSOLE.INFO end
    end

    local function logLine(e)
        local tv = TextView(activity)
        local lp = LinLayoutParams(-1, -2)
        lp.bottomMargin = dp(4)
        tv.setLayoutParams(lp)
        local glyph, color = levelStyle(e.level)
        tv.setText(string.format("[%s] %s %s [%s] %s", e.ts, glyph, e.level, e.tag, e.message))
        tv.setTextColor(color)
        tv.setTextSize(1, 10)
        tv.setTypeface(Typeface.create("monospace", Typeface.NORMAL))
        tv.setPadding(dp(10), dp(6), dp(10), dp(6))
        tv.setBackground(getSkin(UI.BG, 8))
        tv.setClickable(true)
        -- Tap to copy this single entry.
        tv.setOnClickListener(View.OnClickListener({ onClick = function()
            local ok = pcall(function()
                local cm = activity.getSystemService("clipboard")
                cm.setPrimaryClip(ClipData.newPlainText("VOID Log",
                    string.format("[%s] [%s] %s: %s", e.ts, e.level, e.tag, e.message)))
            end)
            showToast(ok and t("copied_one") or T("common.failed"))
        end }))
        return tv
    end

    -- ── Filter chips ("all" | "logs" | "crashes") ─────────────────────────────
    local filter = "all"
    local chipRefs = {}

    -- Level chips (second row): nil = all levels.
    local levelFilter = nil
    local levelRefs   = {}
    local RENDER_CAP  = 150

    -- Forward declaration: the chip closures call populate() before its
    -- definition, which would otherwise resolve to a nil global.
    local populate

    local function refreshChips()
        for key, btn in pairs(chipRefs) do
            if key == filter then
                btn.setBackground(getSkin(UI.ACCENT, 8))
                btn.setTextColor(UI.TEXT)
            else
                btn.setBackground(getSkin(UI.BG, 8, 1, UI.STROKE))
                btn.setTextColor(UI.SUB)
            end
        end
    end

    local function makeChip(label, key)
        local btn = TextView(activity)
        local lp = LinLayoutParams(0, -2, 1.0)
        lp.rightMargin = dp(6)
        btn.setLayoutParams(lp)
        btn.setText(label)
        btn.setTextColor(UI.SUB)
        btn.setGravity(Gravity.CENTER)
        btn.setTypeface(Typeface.create("sans-serif-medium", Typeface.BOLD))
        btn.setTextSize(1, 11)
        btn.setPadding(dp(10), dp(8), dp(10), dp(8))
        btn.setBackground(getSkin(UI.BG, 8, 1, UI.STROKE))
        btn.setOnClickListener(View.OnClickListener({ onClick = function()
            if filter == key then return end
            filter = key
            refreshChips()
            populate()
        end }))
        chipRefs[key] = btn
        return btn
    end

    local function refreshLevelChips()
        for key, btn in pairs(levelRefs) do
            if key == levelFilter then
                btn.setBackground(getSkin(UI.ACCENT, 8))
                btn.setTextColor(UI.TEXT)
            else
                btn.setBackground(getSkin(UI.BG, 8, 1, UI.STROKE))
                btn.setTextColor(UI.SUB)
            end
        end
    end

    -- Tapping the active level chip again clears the filter.
    local function makeLevelChip(label, key)
        local btn = TextView(activity)
        local lp = LinLayoutParams(0, -2, 1.0)
        lp.rightMargin = dp(6)
        btn.setLayoutParams(lp)
        btn.setText(label)
        btn.setTextColor(UI.SUB)
        btn.setGravity(Gravity.CENTER)
        btn.setTypeface(Typeface.create("sans-serif-medium", Typeface.BOLD))
        btn.setTextSize(1, 11)
        btn.setPadding(dp(10), dp(8), dp(10), dp(8))
        btn.setBackground(getSkin(UI.BG, 8, 1, UI.STROKE))
        btn.setOnClickListener(View.OnClickListener({ onClick = function()
            levelFilter = (levelFilter == key) and nil or key
            refreshLevelChips()
            populate()
        end }))
        levelRefs[key] = btn
        return btn
    end

    -- ── Dynamic list (rebuilt on render / refresh / clear) ────────────────────
    local listLayout = LinearLayout(activity)
    listLayout.setOrientation(1)
    setLayoutDir(listLayout)
    listLayout.setLayoutParams(LinLayoutParams(-1, -2))

    function populate()
        listLayout.removeAllViews()

        local crashes = CrashHandler.getCrashes()
        local logs    = CrashHandler.getLogs()
        local showC   = (filter ~= "logs")
        local showL   = (filter ~= "crashes")

        -- Keep chip counts live.
        if chipRefs.all then
            chipRefs.all.setText(t("filter_all"))
            chipRefs.logs.setText(t("filter_logs", #logs))
            chipRefs.crashes.setText(t("filter_crashes", #crashes))
        end

        local rendered = false

        if showC and #crashes > 0 then
            rendered = true
            addModuleSep(listLayout, t("crashes_header", #crashes))
            for i = #crashes, 1, -1 do      -- newest first
                listLayout.addView(crashCard(crashes[i]))
            end
        end

        if showL and #logs > 0 then
            -- Level filter (nil = every level); FATAL shares the ERROR chip.
            local lvLogs = {}
            for i = #logs, 1, -1 do
                local e = logs[i]
                if not levelFilter or levelFilter == e.level
                    or (levelFilter == "ERROR" and e.level == "FATAL") then
                    lvLogs[#lvLogs + 1] = e
                end
            end

            if #lvLogs > 0 then
                rendered = true
                addModuleSep(listLayout, t("logs_header", #lvLogs))
                -- Render the newest RENDER_CAP entries only.
                local total = #lvLogs
                local from  = math.max(1, total - RENDER_CAP + 1)
                for i = from, total do
                    listLayout.addView(logLine(lvLogs[i]))
                end
                if total > RENDER_CAP then
                    local more = TextView(activity)
                    more.setText(t("capped", RENDER_CAP, total))
                    more.setTextColor(UI.SUB)
                    more.setTextSize(1, 10)
                    more.setGravity(Gravity.CENTER)
                    more.setPadding(dp(12), dp(4), dp(12), dp(4))
                    listLayout.addView(more)
                end
            end
        end

        if not rendered then
            local empty = TextView(activity)
            empty.setText(CrashHandler.isEmpty() and t("empty") or t("empty_filtered"))
            empty.setTextColor(UI.SUB)
            empty.setTextSize(1, 12)
            empty.setPadding(dp(12), dp(14), dp(12), dp(14))
            empty.setGravity(Gravity.CENTER)
            empty.setBackground(getSkin(UI.CARD, 10, 1, UI.STROKE))
            listLayout.addView(empty)
        end
    end

    local function copyAll()
        local okc = pcall(function()
            local cm = activity.getSystemService("clipboard")
            cm.setPrimaryClip(ClipData.newPlainText("VOID Console", CrashHandler.formatAll()))
        end)
        showToast(okc and t("copied") or T("common.failed"))
    end

    -- ── Layout ────────────────────────────────────────────────────────────────
    local intro = TextView(activity)
    intro.setText(t("desc"))
    intro.setTextColor(UI.SUB)
    intro.setTextSize(1, 11)
    local ilp = LinLayoutParams(-1, -2)
    ilp.bottomMargin = dp(8)
    intro.setLayoutParams(ilp)
    container.addView(intro)

    -- Filter chips row (ALL / LOGS / CRASHES) with live counts.
    local chips = LinearLayout(activity)
    chips.setOrientation(0)
    setLayoutDir(chips)
    local clp = LinLayoutParams(-1, -2)
    clp.bottomMargin = dp(8)
    chips.setLayoutParams(clp)
    chips.addView(makeChip(t("filter_all"), "all"))
    chips.addView(makeChip(t("filter_logs"), "logs"))
    chips.addView(makeChip(t("filter_crashes"), "crashes"))
    container.addView(chips)

    -- Level chips (ERROR / WARN / INFO / DEBUG) narrow the log stream.
    local lchips = LinearLayout(activity)
    lchips.setOrientation(0)
    setLayoutDir(lchips)
    local llp = LinLayoutParams(-1, -2)
    llp.bottomMargin = dp(8)
    lchips.setLayoutParams(llp)
    lchips.addView(makeLevelChip("ERROR", "ERROR"))
    lchips.addView(makeLevelChip("WARN", "WARN"))
    lchips.addView(makeLevelChip("INFO", "INFO"))
    lchips.addView(makeLevelChip("DEBUG", "DEBUG"))
    container.addView(lchips)

    local row = LinearLayout(activity)
    row.setOrientation(0)
    setLayoutDir(row)
    local rlp = LinLayoutParams(-1, -2)
    rlp.bottomMargin = dp(10)
    row.setLayoutParams(rlp)
    row.addView(makeButton(t("copy_all"), copyAll))
    row.addView(makeButton(t("refresh"),  populate))
    row.addView(makeButton(t("clear"), function()
        CrashHandler.clear()
        populate()
        showToast(t("cleared"))
    end))
    container.addView(row)

    container.addView(listLayout)
    populate()
end

end

__vfs['modules/tabs/creative.lua'] = function(...)
--[[
  Creative Tab — Custom-track features
  UI wiring only. Memory ops live in modules/ops/creative.lua.

  Flow for track features (verify, set length, rename):
    depth 1 → track list   (cancel = exit)
    depth 2 → action pick  (cancel = back to track list)
    depth 3 → action input (cancel = back to action pick)
]]

local ops = CrashHandler.loadFeature("modules/ops/creative.lua")

return function(container)
    local function t(key, ...) return T("creative." .. key, ...) end

    -- ── Any Theme Objects ─────────────────────────────────────────────────────
    addModule(container, "any_theme_objects", t("any_theme_objects.title"), t("any_theme_objects.desc"), "switch", nil,
    function(done, state)
        ops.anyThemeObjects(state, function(ok, errKey, count)
            if ok then
                showToast(t(state and "any_theme_objects.applied" or "any_theme_objects.reverted", tostring(count)))
            else
                showToast(T(errKey or "common.failed"), true)
            end
            done()
        end)
    end)

    -- ── Show Hidden Objects ───────────────────────────────────────────────────
    addModule(container, "show_hidden_objects", t("show_hidden_objects.title"), t("show_hidden_objects.desc"), "switch", nil,
    function(done, state)
        ops.showHiddenObjects(state, function(ok, errKey, count)
            if ok then
                showToast(t(state and "show_hidden_objects.applied" or "show_hidden_objects.reverted", tostring(count)))
            else
                showToast(T(errKey or "common.failed"), true)
            end
            done()
        end)
    end)

    -- ── Copy Any ─────────────────────────────────────────────────────────────
    addArchModule(container, "copy_any", t("copy_any.title"), t("copy_any.desc"), "button", nil,
    offsets.downloadedCustomTracks and function(done)
        ops.copyAny(function(ok, errKey, count)
            if ok then
                showToast(t("copy_any.applied", tostring(count)))
            else
                showToast(T(errKey or "common.failed"), true)
            end
            done()
        end)
    end)

    -- ── Track Editor (verify / set length / rename) ───────────────────────────
    addArchModule(container, "track_editor", t("track_editor.title"), t("track_editor.desc"), "button", nil,
    offsets.customTracks and function(done)
        showToast(t("track_editor.loading"))

        ops.getCustomTracks(function(ok, tracksOrErr)
            if not ok then
                showToast(T(tracksOrErr or "creative.tracks_not_found"), true)
                done(); return
            end

            local tracks = tracksOrErr
            if #tracks == 0 then
                showToast(t("track_editor.no_tracks"), true)
                done(); return
            end

            -- Build display list: "Track Name  [✓]  (500m)" or "Track Name  (500m)"
            local display = {}
            for _, tr in ipairs(tracks) do
                display[#display + 1] = string.format("%s%s  (%dm)",
                    tr.nameStr, tr.isVerified == 1 and " [✓]" or "", tr.length)
            end

            local actions = {
                t("action.verify"),
                t("action.set_length"),
                t("action.rename"),
            }

            -- ── Depth loop ────────────────────────────────────────────────────
            local depth     = 1
            local track     = nil
            local actionIdx = nil

            while true do

                -- ── Depth 1: pick track ───────────────────────────────────────
                if depth == 1 then
                    local choice = showList(t("track_editor.title"), t("track_editor.select"), display)
                    if not choice or choice == 0 then
                        done(); return
                    end
                    track = tracks[choice]
                    depth = 2

                -- ── Depth 2: pick action ──────────────────────────────────────
                elseif depth == 2 then
                    local choice = showList(
                        string.format("%s: %s  |  %s",
                            track.nameStr,
                            track.isVerified == 1 and t("track_status.verified") or t("track_status.not_verified"),
                            t("track_length", tostring(track.length))),
                        t("action.select"),
                        actions
                    )
                    if not choice or choice == 0 then
                        depth = 1
                    else
                        actionIdx = choice
                        depth = 3
                    end

                -- ── Depth 3: action input ─────────────────────────────────────
                elseif depth == 3 then

                    -- ── Verify ───────────────────────────────────────────────
                    if actionIdx == 1 then
                        if track.isVerified == 1 then
                            showToast(t("verify.already_verified"))
                            depth = 2
                        else
                            ops.verifyTrack(track.elemPtr, function(ok2, errKey)
                                if ok2 then
                                    track.isVerified = 1
                                    display[track.index + 1] = string.format("%s [✓]  (%dm)", track.nameStr, track.length)
                                    showToast(t("verify.applied", track.nameStr))
                                else
                                    showToast(T(errKey or "common.failed"), true)
                                end
                                done()
                            end)
                            return
                        end

                    -- ── Set Length ────────────────────────────────────────────
                    elseif actionIdx == 2 then
                        local result = showPrompt(
                            t("set_length.title") .. ": " .. track.nameStr,
                            {{ t("set_length.prompt", tostring(track.length)), "number", tostring(track.length) }}
                        )
                        if not result then
                            depth = 2
                        else
                            local newLen = tonumber(result[1])
                            if not newLen or newLen < 1 then
                                showToast(t("set_length.invalid"), true)
                            else
                                ops.setTrackLength(track.elemPtr, newLen, function(ok2, errKey, applied)
                                    if ok2 then
                                        track.length = applied
                                        display[track.index + 1] = string.format("%s%s  (%dm)",
                                            track.nameStr, track.isVerified == 1 and " [✓]" or "", applied)
                                        showToast(t("set_length.applied", track.nameStr, tostring(applied)))
                                    else
                                        showToast(T(errKey or "common.failed"), true)
                                    end
                                    done()
                                end)
                                return
                            end
                        end

                    -- ── Rename ────────────────────────────────────────────────
                    elseif actionIdx == 3 then
                        local result = showPrompt(
                            t("rename.title") .. ": " .. track.nameStr,
                            {{ t("rename.prompt"), "text", track.nameStr }}
                        )
                        if not result then
                            depth = 2
                        else
                            local newName = result[1]
                            if not newName or newName == "" then
                                showToast(t("rename.empty"), true)
                            else
                                ops.renameTrack(track.elemPtr, newName, function(ok2, errKey, applied)
                                    if ok2 then
                                        display[track.index + 1] = string.format("%s%s  (%dm)",
                                            applied, track.isVerified == 1 and " [✓]" or "", track.length)
                                        track.nameStr = applied
                                        showToast(t("rename.applied", applied))
                                    else
                                        showToast(T(errKey or "common.failed"), true)
                                    end
                                    done()
                                end)
                                return
                            end
                        end
                    end

                end -- depth 3
            end -- while true
        end) -- getCustomTracks callback
    end) -- addArchModule track_editor

end

end

__vfs['modules/tabs/cups.lua'] = function(...)
--[[
  Cups Tab - Cup racing modes
  Features: Adjust countdown, Auto-win, Force boss, Force cup, Set time,
            Unlimited tasks, Rank points bonus

  UI wiring only. Memory ops live in modules/ops/cups.lua.

  @module callback Receives container View to populate with modules
]]

local ops = CrashHandler.loadFeature("modules/ops/cups.lua")

return function(container)
    local function t(key, ...) return T("cups." .. key, ...) end

    addModule(container, "adjust_countdown", t("adjust_countdown.title"), t("adjust_countdown.desc"), "slider",
    {title=t("slider.seconds"), min=0, max=10, current=3},
    function(done, vals)
        ops.adjustCountdown(vals, function(status)
            if status == "applied" then
                showToast(t("adjust_countdown.applied", tostring(vals)), true)
            elseif status == "nebula_unavailable" then
                showToast(T("common.nebula_unavailable"))
            else
                showToast(t("adjust_countdown.failed"))
            end
        end)
        done()
    end)

    addArchModule(container, "auto_win", t("auto_win.title"), t("auto_win.desc"), "switch", nil, aobs.autoWin)

    addArchModule(container, "force_boss", t("force_boss.title"), t("force_boss.desc"), "switch", nil, aobs.forceBoss)

    addModule(container, "force_cup", t("force_cup.title"), t("force_cup.desc"), "switch", nil,
    function(done, state)
        ops.forceCup(state, function(status)
            if status == "not_found" then
                showToast(t("force_cup.not_found"))
            elseif status == "enabled" then
                showToast(t("force_cup.enabled"))
            else
                showToast(t("force_cup.disabled"))
            end
        end)
        done()
    end)
    
    addModule(container, "force_frenzy_mode", t("force_frenzy_mode.title"), t("force_frenzy_mode.desc"), "switch", nil,
    function(done, state)
        ops.forceFrenzyMode(state, function(status)
            if status == "not_found" then
                showToast(t("force_frenzy_mode.not_found"))
            elseif status == "enabled" then
                showToast(t("force_frenzy_mode.enabled"))
            else
                showToast(t("force_frenzy_mode.disabled"))
            end
        end)
        done()
    end)

    addArchModule(container, "set_time", t("set_time.title"), t("set_time.desc"), "input", {
        {hint = t("set_time.hint"), type = "text"},
    }, function(done, vals)
        local function parseTime(str)
            str = str:match("^%s*(.-)%s*$")
            if str:find("-") then return nil, "no_negative" end

            if str:find(":") then
                local min, sec, ms = str:match("^(%d+):(%d+)%.(%d+)$")
                if not min then return nil, "invalid_format" end
                return tonumber(min) * 60 + tonumber(sec) + tonumber("0." .. ms), nil
            elseif str:find("%.") then
                local sec, ms = str:match("^(%d+)%.(%d+)$")
                if not sec then return nil, "invalid_format" end
                return tonumber(sec) + tonumber("0." .. ms), nil
            else
                local sec = tonumber(str)
                if not sec then return nil, "invalid_format" end
                return sec, nil
            end
        end

        local timeSeconds, err = parseTime(vals)
        if err == "no_negative" then
            showToast(t("set_time.no_negative"), true)
            done()
            return
        elseif err or not timeSeconds then
            showToast(t("set_time.invalid_format"), true)
            done()
            return
        end

        ops.setTime(timeSeconds, function(status)
            if status == "not_in_cup" then
                showToast(t("set_time.not_in_cup"), true)
            elseif status == "start_race_first" then
                showToast(t("set_time.start_race_first"), true)
            else
                showToast(t("set_time.applied", vals), true)
            end
        end)
        done()
    end)

    addModule(container, "unlimited_tasks", t("unlimited_tasks.title"), t("unlimited_tasks.desc"), "switch", nil,
    function(done, state)
        ops.unlimitedTasks(state, function(status, count)
            if status == "applied" then
                showToast(t("unlimited_tasks.enabled", count or 0), true)
            elseif status == "reverted" then
                showToast(t("unlimited_tasks.disabled", count or 0), true)
            elseif status == "none_found" then
                showToast(t("unlimited_tasks.none_found"))
            elseif status == "nebula_unavailable" then
                showToast(T("common.nebula_unavailable"))
            else
                showToast(t("unlimited_tasks.failed"))
            end
        end)
        done()
    end)

    addModule(container, "rank_points_bonus", t("rank_points_bonus.title"), t("rank_points_bonus.desc"), "switch", nil,
    function(done, state)
        ops.rankPointsBonus(state, function(status, count)
            if status == "none_found" then
                showToast(t("rank_points_bonus.none_found"))
            elseif status == "boosted" then
                showToast(t("rank_points_bonus.boosted", tostring(count)))
            elseif status == "no_match" then
                showToast(t("rank_points_bonus.no_match"))
            elseif status == "nothing_to_restore" then
                showToast(t("rank_points_bonus.nothing_to_restore"))
            else
                showToast(t("rank_points_bonus.restored", tostring(count)))
            end
        end)
        done()
    end)
end

end

__vfs['modules/tabs/event.lua'] = function(...)
--[[
  Event Tab - Event mode features
  Features: Patch event rewards, Restore events

  UI wiring only. The file/crypto/root pipeline lives in modules/ops/event.lua.
  This tab supplies the interaction callbacks and renders the result.

  @module callback Receives container View to populate with modules
]]

local ops = CrashHandler.loadFeature("modules/ops/event.lua")

return function(container)
    local function t(key, ...) return T("event." .. key, ...) end

    -- Interaction callbacks handed to core for the unavoidable mid-pipeline UI.
    -- chooseEvents used to call raw gg.multiChoice() -- every other picker in
    -- the app (vehicle.lua, creative.lua, settings.lua) already uses the
    -- app's own themed showList() widget, so this one stuck out (native GG
    -- dialog look/behavior instead of the app's UI). Switched to showList in
    -- multi-select mode; it returns an array of selected 1-based indices
    -- rather than gg.multiChoice's full boolean map, so we convert it back
    -- into the boolean-map shape ops/event.lua already expects -- no changes
    -- needed downstream.
    local titleForKey = {
        select_events_patch   = t("patch_rewards.title"),
        select_events_restore = t("restore_events.title"),
    }

    local ui = {
        onProgress = function(key) gg.toast(t(key)) end,
        chooseEvents = function(labels, titleKey, arg)
            local title = titleForKey[titleKey] or t(titleKey, arg)
            local picked = showList(title, t(titleKey, arg), labels, true)
            if not picked then return nil end
            local selections = {}
            for _, idx in ipairs(picked) do
                selections[idx] = true
            end
            return selections
        end,
    }

    -- Localize a failedList entry: { key, arg1, ... } → t(key, arg1, ...)
    local function localizeFail(e) return t(table.unpack(e)) end

    -- Build the success/failed dialog body from the result lists.
    local function buildResultMsg(result, successHeaderKey, successItemKey)
        local resultMsg = ""
        if #result.successList > 0 then
            resultMsg = resultMsg .. t(successHeaderKey) .. "\n"
            for _, name in ipairs(result.successList) do
                resultMsg = resultMsg .. t(successItemKey, name) .. "\n"
            end
            resultMsg = resultMsg .. "\n"
        end
        if #result.failedList > 0 then
            resultMsg = resultMsg .. t("failed_header") .. "\n"
            for _, e in ipairs(result.failedList) do
                resultMsg = resultMsg .. t("failed_item", localizeFail(e)) .. "\n"
            end
        end
        return resultMsg
    end

    -- Wait for any queued scheduler file tasks to drain, then kill + relaunch.
    local function restartGame(finishingKey)
        if scheduler:get_queue_count() > 0 or scheduler:is_processing() then
            gg.toast(t(finishingKey))
            while scheduler:get_queue_count() > 0 or scheduler:is_processing() do
                gg.sleep(100)
            end
        end
        gg.processKill()
        gg.sleep(1000)
        exitScript()
    end

    addModule(container, "patch_rewards", t("patch_rewards.title"), t("patch_rewards.desc"), "button", nil, function(done)
        ops.patchRewards(ui, function(result)
            if result.earlyExit then
                showDialog(t(result.earlyExit[1]), t(result.earlyExit[2], result.earlyExit[3]), {T("common.ok")})
                done()
                return
            end

            local resultMsg = buildResultMsg(result, "success_header", "success_item")
            showDialog(t("patch_results_title"), resultMsg, {T("common.ok")})
            done()

            if result.restart then
                print(resultMsg)
                showDialog(t("restart_required_title"), t("patch_restart_msg"), {T("common.ok")})
                restartGame("finishing_tasks_patch")
            else
                showDialog(T("common.failed"), t("patch_failed_msg"), {T("common.ok")})
            end
        end)
    end)

    addModule(container, "restore_events", t("restore_events.title"), t("restore_events.desc"), "button", nil, function(done)
        ops.restoreEvents(ui, function(result)
            if result.earlyExit then
                showDialog(t(result.earlyExit[1]), t(result.earlyExit[2], result.earlyExit[3]), {T("common.ok")})
                done()
                return
            end

            local resultMsg = buildResultMsg(result, "success_removed_header", "success_item_json")
            showDialog(t("restore_results_title"), resultMsg, {T("common.ok")})
            done()

            if result.restart then
                print(resultMsg)
                showDialog(t("restart_required_title"), t("restore_restart_msg"), {T("common.ok")})
                restartGame("finishing_tasks_restore")
            end
        end)
    end)

    -- "applied"/"reverted" toasts are per-card, everything else
    -- (resolve_failed | failed | nebula_unavailable | no_vehicles) is shared.
    local function epToast(card, status)
        if status == "applied" or status == "reverted" then
            showToast(t(card .. "." .. status))
        else
            showToast(t("ep." .. status), true)
        end
    end

    addModule(container, "unlimited_vehicle_usage", t("unlimited_vehicle_usage.title"),
        t("unlimited_vehicle_usage.desc"), "switch", nil, function(done, state)
        ops.unlimitedVehicleUsage(state, function(status)
            epToast("unlimited_vehicle_usage", status)
        end)
        done()
    end)

    addModule(container, "allow_all_vehicles", t("allow_all_vehicles.title"),
        t("allow_all_vehicles.desc"), "switch", nil, function(done, state)
        ops.allowAllVehicles(state, function(status)
            epToast("allow_all_vehicles", status)
        end)
        done()
    end)

    addModule(container, "free_entry_fee", t("free_entry_fee.title"),
        t("free_entry_fee.desc"), "switch", nil, function(done, state)
        ops.freeEntryFee(state, function(status)
            epToast("free_entry_fee", status)
        end)
        done()
    end)

    addModule(container, "vehicle_bonuses", t("vehicle_bonuses.title"),
        t("vehicle_bonuses.desc"), "switch", nil, function(done, state)
        ops.vehicleBonuses(state, function(status)
            epToast("vehicle_bonuses", status)
        end)
        done()
    end)

    addModule(container, "custom_participants", t("custom_participants.title"),
        t("custom_participants.desc"), "input", {
        { hint = t("custom_participants.hint"), value = "16", type = "number" },
    }, function(done, val)
        local n = math.floor(tonumber(val) or 0)
        if n < 1 then
            showToast(t("custom_participants.invalid"), true)
            done(); return
        end
        if n > 2147483647 then n = 2147483647 end
        if n > 100 then showToast(t("custom_participants.warn_big"), true) end
        ops.customParticipants(n, function(status)
            epToast("custom_participants", status)
        end)
        done()
    end)

    addModule(container, "custom_duration", t("custom_duration.title"),
        t("custom_duration.desc"), "input", {
        { hint = t("custom_duration.hint"), value = "300", type = "number" },
    }, function(done, val)
        local n = math.floor(tonumber(val) or 0)
        if n < 1 then
            showToast(t("custom_duration.invalid"), true)
            done(); return
        end
        if n > 2147483647 then n = 2147483647 end
        if n > 3600 then showToast(t("custom_duration.warn_big"), true) end
        ops.customDuration(n, function(status)
            epToast("custom_duration", status)
        end)
        done()
    end)

    addModule(container, "instant_ticket_refill", t("instant_ticket_refill.title"),
        t("instant_ticket_refill.desc"), "switch", nil, function(done, state)
        ops.instantTicketRefill(state, function(status)
            epToast("instant_ticket_refill", status)
        end)
        done()
    end)
end

end

__vfs['modules/tabs/other.lua'] = function(...)
--[[
  Other Tab - Misc features
  Features: Debug mode, Change aspect ratio, Set resolution, Set resolution offset

  UI wiring only. Memory ops live in modules/ops/other.lua.
  done() is called right after dispatch (not inside the result callback) so a
  crash in the scheduled work can't leave a card stuck.

  @module callback Receives container View to populate with modules
]]

local ops = CrashHandler.loadFeature("modules/ops/other.lua")

-- Aspect-ratio presets (index matches other.aspect_ratio.options), applied as a
-- matching resolution at 1080p height via the shared resolution op.
local RATIOS = {
    { w = 1920, h = 1080 }, -- 16:9
    { w = 2160, h = 1080 }, -- 18:9
    { w = 2340, h = 1080 }, -- 19.5:9
