__vfs['modules/tabs/settings.lua'] = function(...)
--[[
  Settings Tab - Script settings and UI customization
  Features: background opacity, background RGB,
            accent RGB, logo RGB, sub-text RGB

  All color preferences are saved globally (PID-independent) via
  storage:save_global so they survive game restarts without being cleared
  by a process change.
]]


-- =========================
-- Helpers
-- =========================
local function deepCopy(orig, seen)
    if type(orig) ~= "table" then
        return orig
    end
    if seen and seen[orig] then
        return seen[orig]
    end
    local copy = {}
    seen = seen or {}
    seen[orig] = copy
    for k, v in pairs(orig) do
        copy[deepCopy(k, seen)] = deepCopy(v, seen)
    end
    return copy
end

local function getFileName(path)
    path = tostring(path or "")
    local name = path:match("([^/\\]+)$") or "background image.png"
    name = name:gsub("[^%w%._%-]", "_")
    if name == "" then
        name = "background image.png"
    end
    return name
end

local function safeJoinPath(folder, name)
    folder = tostring(folder or "")
    name = getFileName(name)
    if folder:sub(-1) == "/" then
        return folder .. name
    end
    return folder .. "/" .. name
end

local function bytesToHex(data)
    if type(data) ~= "string" then
        return nil
    end
    return (data:gsub(".", function(c)
        return string.format("%02x", string.byte(c))
    end))
end

local function hexToBytes(hex)
    if type(hex) ~= "string" then
        return nil
    end
    hex = hex:gsub("%s+", "")
    if hex == "" then
        return ""
    end
    if #hex % 2 ~= 0 then
        return nil
    end
    local out = hex:gsub("..", function(cc)
        local n = tonumber(cc, 16)
        if not n then
            return ""
        end
        return string.char(n)
    end)
    return out
end

local function serializeValue(v, seen)
    local t = type(v)
    if t == "string" then
        return string.format("%q", v)
    elseif t == "number" or t == "boolean" then
        return tostring(v)
    elseif t == "table" then
        if seen and seen[v] then
            return "nil"
        end
        seen = seen or {}
        seen[v] = true
        local parts = {}
        for k, val in pairs(v) do
            local keyType = type(k)
            local keyStr
            if keyType == "string" then
                keyStr = "[" .. string.format("%q", k) .. "]"
            elseif keyType == "number" then
                keyStr = "[" .. tostring(k) .. "]"
            elseif keyType == "boolean" then
                keyStr = "[" .. tostring(k) .. "]"
            else
                goto continue
            end
            local valueStr = serializeValue(val, seen)
            if valueStr ~= nil then
                parts[#parts + 1] = keyStr .. "=" .. valueStr
            end
            ::continue::
        end
        return "{" .. table.concat(parts, ",") .. "}"
    end
    return nil
end

local function serializeTable(t)
    return "return " .. serializeValue(t)
end

-- Tears down the current menuView, rebuilds it, and switches to it.
-- The correct sequence is: remove → build → switch.
-- switchToMenu() reads the global menuView, so createMenuView() must run
-- (and set menuView) before switchToMenu() is called.
local function rebuildMenu()
    MainHandler.post(function()
        -- Remove whichever overlay is currently visible.
        if activeView then
            pcall(function() windowManager.removeView(activeView) end)
        end
        menuView   = nil
        activeView = nil

        -- Build the new menu, restoring the Settings tab.
        createMenuView("settings")

        -- Now menuView is set; switch to it.
        switchToMenu()
    end)
end

local function saveAndRefresh()
    LOG.info("Settings", "UI preferences saved and refresh triggered")
    storage:save_global("ui_prefs", UI)
    MainHandler.post(function()
        if menuView then
            menuView.setBackground(getSkin(UI.BG, 16, 0, UI.STROKE))
        end
        if activeTabView then
            loadCategory("settings", activeTabView)
        end
    end)
end

local function applyTheme(shareId)
    local TAG = "ApplyTheme"
    if shareId and shareId ~= "" then
        local rawText, err = paste.get("https://paste.rs/" .. shareId)
        if rawText then
            local ok, exportData = pcall(load(rawText))
            if ok and type(exportData) == "table" and exportData.version then
                for k, v in pairs(exportData.ui) do
                    -- Icon Style is a personal layout preference, not part of
                    -- a shared theme's colors — never let an installed/imported
                    -- theme change it (see also export_theme, which strips it
                    -- before sharing so it never even ends up in exportData.ui).
                    if UI[k] ~= nil and k ~= "ICON_STYLE" then
                        UI[k] = deepCopy(v)
                    end
                end
                if exportData.img_url then
                    showToast(t("theme_downloading_bg"))
                    local dest = gg.FILES_DIR .. "/" .. (exportData.name or "background_image_" .. tostring(os.time()) .. ".png")
                    local path, dErr = catbox.download(exportData.img_url, dest)
                    if path then
                        UI.BG_IMAGE.PATH = path
                    else
                        LOG.error(TAG, "Background image download failed")
                    end
                else
                    UI.BG_IMAGE.PATH = "no_media"
                end
                storage:save_global("ui_prefs", UI)
                saveAndRefresh()
                showDialog(T("common.success"), t("theme_imported"), T("common.ok"))
            else
                showDialog(T("common.failed"), t("theme_invalid_bundle"), T("common.ok"))
            end
        else
            showDialog(T("common.failed"), t("theme_cloud_error", tostring(err)), T("common.ok"))
        end
    end
end

return function(container)

    -- Shorthand for this tab's translation namespace: t("auto_update.title")
    -- instead of T("settings.auto_update.title").
    local function t(key, ...) return T("settings." .. key, ...) end

    -- --- Updater ────────────────────────────────────────────────────────
    
    addModuleSep(container, t("section_updates"))
    
    -- ── Auto Update switch ────────────────────────────────────────────────────────
    addModule(container, "auto_update", t("auto_update.title"), t("auto_update.desc"), "switch", nil, function(done, state)
        if IS_DEV then
            showDialog(t("dev_mode_title"), t("auto_update.dev_mode_msg"), {T("common.ok")})
        else
            storage:save_global("auto_update", state)
        end
        done()
    end)
    
    -- ── Check for Update button ───────────────────────────────────────────────────
    addModule(container, "check_updates", t("check_updates.title"), t("check_updates.desc"), "button", nil, function(done)
        if IS_DEV then
            showDialog(t("dev_mode_title"), t("check_updates.dev_mode_msg"), {T("common.ok")})
            done()
            return
        end
    
        showToast(t("check_updates.checking"))
        local remote_ver, download_url, release_body = fetchLatestVersion()

        if not remote_ver then
            showDialog(t("check_updates.failed_title"), t("check_updates.failed_msg", tostring(download_url)), {T("common.ok")})
            done()
            return
        end
    
        if not versionNewer(remote_ver, CURRENT_VERSION) then
            showDialog(t("check_updates.up_to_date_title"), t("check_updates.up_to_date_msg", CURRENT_VERSION), {T("common.ok")})
            done()
            return
        end
    
        local msg = t("check_updates.available_msg", remote_ver, CURRENT_VERSION, release_body or t("check_updates.no_changelog"))
        showDialog(T("main.update_available_title"), msg, {T("common.update_button"), function()
            if not download_url then
                showDialog(T("common.failed"), t("check_updates.no_asset_msg"), {T("common.ok")})
                return
            end
    
            showToast(T("main.downloading_version", remote_ver))
            local content, err = paste.get(download_url)
            if not content then
                showDialog(t("check_updates.download_failed_title"), tostring(err), {T("common.ok")})
                return
            end
    
            local f = io.open(SCRIPT_PATH, "w")
            if not f then
                showDialog(t("check_updates.write_failed_title"), T("main.update_write_failed_msg", SCRIPT_PATH), {T("common.ok")})
                return
            end
            f:write(content)
            f:close()
    
            showDialog(t("check_updates.done_title"), t("check_updates.done_msg", remote_ver), {t("check_updates.restart_button"), function()
                MainHandler.post(function() os.exit() end)
            end}, {T("common.later")})
        end}, {T("common.cancel")})
    
        done()
    end)
    
    -- ── Language ──────────────────────────────────────────────────────────────
    addModuleSep(container, t("section_language"))

    do
        local langOptions     = {}
        local currentIndex    = 1
        for i, lang in ipairs(LANG_AVAILABLE) do
            langOptions[i] = lang.name
            if lang.code == LANG_CODE then currentIndex = i end
        end

        addModule(container, "language", t("language.title"), t("language.desc"), "spinner",
        { options = langOptions, default = currentIndex },
        function(done, item, index)
            local lang = LANG_AVAILABLE[index]
            if lang and setLanguage(lang.code) then
                showToast(t("language.changed", lang.name))
                showDialog(T("common.success"), t("language.restart_msg"), {T("common.ok")})
                done()
                rebuildMenu()
            else
                showToast(t("language.failed"))
                done()
            end
        end)
    end
    
    -- ── Read-only info ────────────────────────────────────────────────────────

    -- ── Log Management & Feedback ────────────────────────────────────────────
    addModuleSep(container, t("section_log_management"))

    -- Shared rate limiter (5s cooldown across send-log and feedback)
    local _last_action_time = 0
    local RATE_LIMIT_SEC    = 5

    local function check_rate_limit()
        local now = os.time()
        if (now - _last_action_time) < RATE_LIMIT_SEC then
            local remaining = RATE_LIMIT_SEC - (now - _last_action_time)
            showToast(t("rate_limit_msg", tostring(remaining)))
            return false
        end
        _last_action_time = now
        return true
    end

    addModule(container, "send_log", t("send_log.title"), t("send_log.desc"), "button", nil, function(done)
        local TAG_WH = "SendLog"

        if not check_rate_limit() then done() return end

        showToast(t("send_log.sending"))

        local wh = webhook.new("User Log")

        LOG.flush()

        local log_content = ""
        local f = io.open(LOG.path, "r")
        if f then
            log_content = f:read("*a") or ""
            f:close()
        end

        if log_content == "" then
            showDialog(t("send_log.empty_title"), t("send_log.empty_msg"), {T("common.ok")})
            done()
            return
        end

        local ok, code = wh:file(log_content, t("send_log.caption"))
        if ok then
            LOG.info(TAG_WH, "Log uploaded to cloud (HTTP " .. tostring(code) .. ")")
            showDialog(t("send_log.success_title"), t("send_log.success_msg"), {T("common.ok")})
        else
            LOG.error(TAG_WH, "Cloud upload failed: " .. tostring(code))
            showDialog(t("send_log.failed_title"), t("send_log.failed_msg", tostring(code)), {T("common.ok")})
        end

        done()
    end)

    addModule(container, "clear_log", t("clear_log.title"), t("clear_log.desc"), "button", nil, function(done)
        local TAG_CL = "ClearLog"
        local path = LOG.path
        if not path or path == "" then
            showDialog(T("common.failed"), t("clear_log.no_path_msg"), {T("common.ok")})
            done()
            return
        end

        local f, err = io.open(path, "w")
        if f then
            f:close()
            LOG.info(TAG_CL, "Log file cleared by user")
            showDialog(t("clear_log.success_title"), t("clear_log.success_msg"), {T("common.ok")})
        else
            showDialog(T("common.failed"), t("clear_log.failed_msg", tostring(err)), {T("common.ok")})
        end

        done()
    end)

    -- ── Feedback ──────────────────────────────────────────────────────────────
    addModuleSep(container, t("section_feedback"))

    addModule(container, "send_feedback", t("feedback.title"), t("feedback.desc"), "button", nil, function(done)
        local TAG_FB = "Feedback"

        if not check_rate_limit() then done() return end

        -- Step 1: pick category
        local category_keys = { "bug_report", "feature_request", "general" }
        local category_labels = {
            t("feedback.cat_bug"),
            t("feedback.cat_feature"),
            t("feedback.cat_general"),
        }

        local cat_choice = showList(t("feedback.pick_category"), t("feedback.pick_category_desc"), category_labels)
        if not cat_choice or cat_choice == 0 then done() return end

        local category   = category_labels[cat_choice]
        local cat_color  = ({ 0xED4245, 0x5865F2, 0x57F287 })[cat_choice]
        local cat_emoji  = ({ "🐛", "✨", "💬" })[cat_choice]

        -- Step 2: type message
        local result = showPrompt(t("feedback.write_title"), {
            { t("feedback.write_hint"), "text", "" }
        })
        if not result or not result[1] or result[1] == "" then done() return end

        local message = result[1]
        if #message < 5 then
            showDialog(t("feedback.too_short_title"), t("feedback.too_short_msg"), {T("common.ok")})
            done()
            return
        end

        showToast(t("feedback.sending"))

        local wh = webhook.new("User Feedback")
        local ok, code = wh:embed({
            title       = cat_emoji .. "  " .. category,
            description = message,
            color       = cat_color,
            fields      = {
                { name = t("feedback.field_version"), value = tostring(CURRENT_VERSION or "?"), inline = true },
                { name = t("feedback.field_arch"),    value = tostring(DEVICE_ARCH     or "?"), inline = true },
            },
            footer    = { text = "VOID Feedback" },
            timestamp = true,
        })

        if ok then
            LOG.info(TAG_FB, "Feedback sent: [" .. category .. "] " .. message)
            showDialog(t("feedback.success_title"), t("feedback.success_msg"), {T("common.ok")})
        else
            LOG.error(TAG_FB, "Feedback send failed: " .. tostring(code))
            showDialog(t("feedback.failed_title"), t("feedback.failed_msg"), {T("common.ok")})
        end

        done()
    end)

    -- ── Console ───────────────────────────────────────────────────────────────
    addModuleSep(container, t("section_console"))

    do
        local crashCap, logCap = CrashHandler.getCaps()

        addModule(container, "console_crash_cap", t("console_crash_cap.title"), t("console_crash_cap.desc"),
        "slider", { min = 5, max = 500, current = crashCap, title = t("console_crash_cap.slider") },
        function(done, val)
            local n = tonumber(val) or crashCap
            CrashHandler.setCaps(n, nil)   -- nil = keep existing log cap
            showToast(t("console_cap_applied", tostring(n)))
            done()
        end)

        addModule(container, "console_log_cap", t("console_log_cap.title"), t("console_log_cap.desc"),
        "slider", { min = 5, max = 2000, current = logCap, title = t("console_log_cap.slider") },
        function(done, val)
            local n = tonumber(val) or logCap
            CrashHandler.setCaps(nil, n)   -- nil = keep existing crash cap
            showToast(t("console_cap_applied", tostring(n)))
            done()
        end)
    end

    -- ── Custom Colors Info ────────────────────────────────────────────────────
    -- Allow user to change colors of this script.
    addModuleSep(container, t("section_ui_customizations"))
    
    addModule(container, "theme_store", t("theme_store.title"), t("theme_store.desc"), "button", nil,
    function(done)
        local TAG = "ThemeStore"
        LOG.info(TAG, "Opening theme store...")

        local raw, err = paste.get("https://raw.githubusercontent.com/vekendianorg/void-themes/refs/heads/main/index.json")
        if not raw then
            showDialog(T("common.failed"), t("theme_store.unreachable_msg", tostring(err)), {T("common.ok")})
            done()
            return
        end

        local index = nil
        local ok, parseErr = pcall(function()
            index = json.decode(raw)
        end)

        if not ok or not index or not index.themes then
            showDialog(T("common.failed"), t("theme_store.parse_failed_msg"), {T("common.ok")})
            done()
            return
        end

        local allThemes = index.themes
        local currentThemes = allThemes

        local function openStore(allThemes, currentThemes)
            local isFiltered = currentThemes ~= allThemes
            local title = t("theme_store.list_title")
            local desc  = isFiltered
                and t("theme_store.search_results_desc", tostring(#currentThemes))
                or  t("theme_store.available_desc", tostring(#allThemes))
        
            local items = {}
            for _, theme in ipairs(currentThemes) do
                table.insert(items, theme.name .. " • " .. t("theme_store.by_author", theme.author))
            end
        
            -- Search as first item
            table.insert(items, 1, t("theme_store.search_item"))
            if isFiltered then
                table.insert(items, 2, t("theme_store.clear_search_item"))
            end
        
            return showList(title, desc, items)
        end

        -- Store loop
        local refreshMenu = false
        while true do
            local choice = openStore(allThemes, currentThemes)
        
            if choice == 0 then
                break -- cancelled / outside tap
        
            elseif choice == 1 then
                -- Search
                local result = showPrompt(t("theme_store.search_title"), {
                    {t("theme_store.search_hint"), "text", ""}
                })
                if result and result[1] ~= "" then
                    local q = result[1]:lower()
                    local filtered = {}
                    for _, theme in ipairs(allThemes) do
                        if theme.name:lower():find(q, 1, true)
                        or theme.author:lower():find(q, 1, true)
                        or (theme.description and theme.description:lower():find(q, 1, true)) then
                            table.insert(filtered, theme)
                        end
                    end
                    
                    currentThemes = filtered
                    
                    if #filtered == 0 then
                        showToast(t("theme_store.no_results", result[1]))
                    end
                end
        
            elseif currentThemes ~= allThemes and choice == 2 then
                -- Clear search
                currentThemes = allThemes
        
            else
                -- Theme selected — offset by search + clear buttons
                local offset = currentThemes ~= allThemes and 2 or 1
                local theme = currentThemes[choice - offset]
                if theme then
                    local choice = showDialog(
                        theme.name,
                        t("theme_store.detail_msg", theme.author, theme.description or "", theme.id),
                        {t("theme_store.install_button"), function() applyTheme(theme.id); refreshMenu = true end}, {T("common.cancel")}
                    )
                end
            end
            if refreshMenu then break end
        end
        
        done()
        rebuildMenu()
    end)
    
    addModule(container, "reset_theme", t("reset_theme.title"), t("reset_theme.desc"), "button", nil, function(done)
        local TAG = "ResetTheme"
        LOG.info(TAG, "User triggered theme reset")
        
        storage:delete_global("ui_prefs")
        UI = loadModule("configs/app/colors.lua")

        -- Icon Style is a personal layout preference, not a theme color —
        -- "Reset Theme" should only reset colors/background, so re-apply it.
        local saved_icon_style = storage:load_global("icon_style")
        if saved_icon_style then UI.ICON_STYLE = saved_icon_style end
        
        done()
        rebuildMenu()
        MainHandler.post(function() iconView = createIconView() end)
    end)
    
    addModule(container, "import_theme", t("import_theme.title"), t("import_theme.desc"), "input", {
        { hint = t("import_theme.hint"), value = "", type = "text" }
    }, function(done, val)
        local TAG = "ImportTheme"
        local shareId = (type(val) == "table") and val[1] or val
        LOG.info(TAG, "Importing theme with share ID: " .. tostring(shareId))
        
        applyTheme(shareId)
    
        done()
        rebuildMenu()
    end)
    
    addModule(container, "export_theme", t("export_theme.title"), t("export_theme.desc"), "button", nil, function(done)
        local TAG = "ExportTheme"
        LOG.info(TAG, "User triggered theme export")
        local exportUI = deepCopy(UI)
        -- Icon Style is a personal layout preference, not a shareable theme
        -- color — strip it so installing this theme never touches someone
        -- else's icon shape choice.
        exportUI.ICON_STYLE = nil
    
        local function finalizeExport(imageUrl)
            local exportData = {
                version = 5,
                kind = "theme_bundle_url",
                name = (UI.BG_IMAGE.PATH:match("([^/\\]+)$") or "background_image_" .. tostring(os.time()).. ".png"),
                ui = exportUI,
                img_url = imageUrl
            }
    
            local payload = serializeTable(exportData)
            local link, err = paste.post(payload)
    
            if link then
                local pasteId = link:match("[^/]+$")
                gg.copyText(pasteId)
                showDialog(T("common.success"), t("export_theme.share_id_msg", pasteId), T("common.ok"))
            else
                showDialog(T("common.failed"), t("export_theme.upload_failed_msg", tostring(err)), T("common.ok"))
            end
            done()
        end
    
        if UI.BG_IMAGE and UI.BG_IMAGE.PATH and UI.BG_IMAGE.PATH ~= "no_media" then
            showDialog(t("export_theme.size_warning_title"), t("export_theme.size_warning_msg"),
            {T("common.yes"), function()
                showToast(t("export_theme.uploading_bg"))
                local url, err = catbox.upload(UI.BG_IMAGE.PATH)
                if url then finalizeExport(url) else showDialog(t("export_theme.image_upload_failed_title"), t("export_theme.image_upload_failed_msg", err), T("common.ok")); done() end
            end},
            {T("common.no")})
        else
            finalizeExport(nil)
        end
        
        done()
    end)
    
    -- Tabs icon
    addModule(container, "tabs_icon", t("tabs_icon.title"), t("tabs_icon.desc"), "input", {
        { hint = t("tabs_icon.hint"), value = UI.TABS_ICON, type = "text" }
    }, function(done, val)
        if val == nil or val == "" then
            showToast(t("tabs_icon.empty_error"))
            done()
        else
            UI.TABS_ICON = val
            saveAndRefresh()
            done()
            rebuildMenu()
        end
    end)

    -- ── Background Opacity ────────────────────────────────────────────────────
    -- Writes to the alpha byte of UI.BG; HEADER, CARD, and GLASS track it at
    -- fixed ratios so the visual hierarchy stays consistent.

    local function getAlpha(color)
        return (color >> 24) & 0xFF
    end

    local function setLayerAlpha(a)
        local function recolor(base, ratio)
            return (math.min(math.floor(a * ratio), 0xFF) << 24) | (base & 0x00FFFFFF)
        end
        UI.BG = recolor(UI.BG, 1.00)
        UI.HEADER = recolor(UI.HEADER, 1.25)
        UI.CARD = recolor(UI.CARD, 1.55)
        UI.GLASS = recolor(UI.GLASS, 0.75)
    end

    addModule(container, "bg_opacity", t("bg_opacity.title"),
        t("bg_opacity.desc"),
        "slider",
        {min = 1, max = 255, current = getAlpha(UI.BG), title = t("slider.alpha")},
        function(done, val)
            setLayerAlpha(val)
            saveAndRefresh()
            done()
        end
    )
    
    -- ── Background Image Opacity ─────────────────────
    addModule(container, "bg_image_opacity", t("bg_image_opacity.title"),
        t("bg_image_opacity.desc"),
        "slider",
        {min = 0, max = 255, current = UI.BG_IMAGE.ALPHA & 0xFF, title = t("slider.alpha")},
        function(done, val) 
            UI.BG_IMAGE.ALPHA = val & 0xFF
            
            saveAndRefresh()
            done()
            rebuildMenu()
        end
    )

    -- ── Background Image ────────────────────────────────────────────────
    -- Updates the absolute storage location path pointing to the background image image.

    addModule(container, "bg_image_picker", t("bg_image_picker.title"), t("bg_image_picker.desc"), "button", nil, function(done)
        local response = gg.prompt(
            { t("bg_image_picker.path_label"), t("bg_image_picker.remove_label") },
            { UI.BG_IMAGE.PATH == "no_media" and gg.EXT_STORAGE or UI.BG_IMAGE.PATH, false },
            { "file", "checkbox" }
        )
        
        if response then
            if response[2] == true then
                UI.BG_IMAGE.PATH = "no_media"
                saveAndRefresh()
                showDialog(t("bg_image_picker.success_title"), t("bg_image_picker.removed_msg"), {T("common.ok")})
            else
                if response[1] then
                    local parsedPath = response[1]:gsub("^%s*(.-)%s*$", "%1")
        
                    if parsedPath ~= "" then
                        local verificationHandle = io.open(parsedPath, "r")
                        
                        if verificationHandle then
                            verificationHandle:close()
                            
                            UI.BG_IMAGE.PATH = parsedPath
                            saveAndRefresh()
                            showDialog(t("bg_image_picker.success_title"), t("bg_image_picker.added_msg"), {T("common.ok")})
                        else
                            showDialog(T("common.failed"), t("bg_image_picker.not_found_msg", tostring(parsedPath)), {T("common.ok")})
                        end
                    end
                end
            end
        end
        
        done()
        rebuildMenu()
    end)

    -- ── Background RGB ────────────────────────────────────────────────────────
    -- Adjusts the R, G, B hue of UI.BG. HEADER and CARD are derived at fixed
    -- brightness ratios so the layer hierarchy stays intact. Alphas are
    -- preserved as-is (use Background Opacity to change them).

    local function setBgRgb(r, g, b)
        local function recolorRgb(base, ratio)
            local a = (base >> 24) & 0xFF
            local nr = math.min(math.floor(r * ratio), 0xFF)
            local ng = math.min(math.floor(g * ratio), 0xFF)
            local nb = math.min(math.floor(b * ratio), 0xFF)
            return (a << 24) | (nr << 16) | (ng << 8) | nb
        end
        UI.BG = recolorRgb(UI.BG, 1.00)
        UI.HEADER = recolorRgb(UI.HEADER, 1.30)
        UI.CARD = recolorRgb(UI.CARD, 1.55)
    end

    addModule(container, "bg_rgb", t("bg_rgb.title"),
        t("bg_rgb.desc"),
        "slider",
        {
            {min = 0, max = 255, current = (UI.BG >> 16) & 0xFF, title = t("slider.r")},
            {min = 0, max = 255, current = (UI.BG >> 8) & 0xFF, title = t("slider.g")},
            {min = 0, max = 255, current = UI.BG & 0xFF, title = t("slider.b")},
        },
        function(done, vals)
            setBgRgb(vals[1], vals[2], vals[3])
            saveAndRefresh()
            done()
        end
    )

    -- ── Accent RGB ────────────────────────────────────────────────────────────
    -- ACCENT uses fixed alpha 0x60 (38% opaque).
    -- MUTED is derived automatically at alpha 0x4D with each channel halved.

    local function buildAccent(r, g, b)
        UI.ACCENT = (0x60 << 24) | (r << 16) | (g << 8) | b
        UI.MUTED = (0x4D << 24) | ((r >> 1) << 16) | ((g >> 1) << 8) | (b >> 1)
    end

    addModule(container, "accent_rgb", t("accent_rgb.title"),
        t("accent_rgb.desc"),
        "slider",
        {
            {min = 0, max = 255, current = (UI.ACCENT >> 16) & 0xFF, title = t("slider.r")},
            {min = 0, max = 255, current = (UI.ACCENT >> 8) & 0xFF, title = t("slider.g")},
            {min = 0, max = 255, current = UI.ACCENT & 0xFF, title = t("slider.b")},
        },
        function(done, vals)
            buildAccent(vals[1], vals[2], vals[3])
            saveAndRefresh()
            done()
        end
    )

    -- ── Logo (Highlight) RGB ──────────────────────────────────────────────────
    -- LOGO is always fully opaque (alpha 0xFF).
    -- Used for labels, icons, slider arrows, and the wordmark.

    local function buildLogo(r, g, b)
        UI.LOGO = (0xFF << 24) | (r << 16) | (g << 8) | b
    end

    addModule(container, "logo_rgb", t("logo_rgb.title"),
        t("logo_rgb.desc"),
        "slider",
        {
            {min = 0, max = 255, current = (UI.LOGO >> 16) & 0xFF, title = t("slider.r")},
            {min = 0, max = 255, current = (UI.LOGO >> 8) & 0xFF, title = t("slider.g")},
            {min = 0, max = 255, current = UI.LOGO & 0xFF, title = t("slider.b")},
        },
        function(done, vals)
            buildLogo(vals[1], vals[2], vals[3])
            saveAndRefresh()
            done()
        end
    )

    -- ── Sub-text RGB ──────────────────────────────────────────────────────────
    -- SUB uses fixed alpha 0xDD (87% opaque).
    -- Used for descriptions and inactive tab labels.

    local function buildSub(r, g, b)
        UI.SUB = (0xDD << 24) | (r << 16) | (g << 8) | b
    end

    addModule(container, "sub_rgb", t("sub_rgb.title"),
        t("sub_rgb.desc"),
        "slider",
        {
            {min = 0, max = 255, current = (UI.SUB >> 16) & 0xFF, title = t("slider.r")},
            {min = 0, max = 255, current = (UI.SUB >> 8) & 0xFF, title = t("slider.g")},
            {min = 0, max = 255, current = UI.SUB & 0xFF, title = t("slider.b")},
        },
        function(done, vals)
            buildSub(vals[1], vals[2], vals[3])
            saveAndRefresh()
            done()
        end
    )
    
    -- ── Text RGB ──────────────────────────────────────────────────────────────
    -- Main text color used throughout the menu.
    
    local function buildText(r, g, b)
        UI.TEXT = (0xFF << 24) | (r << 16) | (g << 8) | b
        -- NOTE: UI.LOGO is its own independent slider (see logo_rgb above) —
        -- it must NOT be overwritten here, otherwise a user who customizes
        -- Highlight RGB loses it the moment they touch Text RGB.
    end
    
    addModule(container, "text_rgb", t("text_rgb.title"),
        t("text_rgb.desc"),
        "slider",
        {
            {min = 0, max = 255, current = (UI.TEXT >> 16) & 0xFF, title = t("slider.r")},
            {min = 0, max = 255, current = (UI.TEXT >> 8) & 0xFF, title = t("slider.g")},
            {min = 0, max = 255, current = UI.TEXT & 0xFF, title = t("slider.b")},
        },
        function(done, vals)
            buildText(vals[1], vals[2], vals[3])
            saveAndRefresh()
            done()
        end
    )

    -- ── Window Size ───────────────────────────────────────────────────────────
    
    addModule(container, "win_width", t("win_width.title"),
        t("win_width.desc", RESIZE_MIN_W, RESIZE_MAX_W),
        "slider",
        {min = RESIZE_MIN_W, max = RESIZE_MAX_W, current = WIN_W, title = t("slider.width")},
        function(done, val)
            applyWindowResize(val, WIN_H)
            done()
        end
    )

    addModule(container, "win_height", t("win_height.title"),
        t("win_height.desc", RESIZE_MIN_H, RESIZE_MAX_H),
        "slider",
        {min = RESIZE_MIN_H, max = RESIZE_MAX_H, current = WIN_H, title = t("slider.height")},
        function(done, val)
            applyWindowResize(WIN_W, val)
            done()
        end
    )

    -- ── Icon Style ────────────────────────────────────────────────────────────
    -- Switches the minimized-state icon between the original full-width pill
    -- and a compact circular/rounded-square "V" bubble.

    do
        local ICON_STYLE_OPTIONS = { "pill", "circle", "square" }
        local styleLabels = {
            t("icon_style.pill"), t("icon_style.circle"), t("icon_style.square"),
        }
        local currentIndex = 1
        for i, style in ipairs(ICON_STYLE_OPTIONS) do
            if UI.ICON_STYLE == style then currentIndex = i end
        end

        addModule(container, "icon_style", t("icon_style.title"), t("icon_style.desc"),
            "spinner",
            { options = styleLabels, default = currentIndex },
            function(done, item, index)
                UI.ICON_STYLE = ICON_STYLE_OPTIONS[index] or "pill"
                -- Dedicated global key (independent of "ui_prefs") so theme
                -- reset/import never wipes this choice — see main.lua load
                -- and the reset_theme / applyTheme handlers below.
                storage:save_global("icon_style", UI.ICON_STYLE)
                saveAndRefresh()
                -- Rebuild the (currently hidden, since we're inside the full
                -- menu) icon view so the next minimize uses the new style.
                MainHandler.post(function() iconView = createIconView() end)
                showToast(t("icon_style.changed", styleLabels[index]))
                done()
            end
        )
    end

end

end

__vfs['modules/tabs/shop.lua'] = function(...)
--[[
  Shop Tab - Shop mode features
  Features: Free chest, Free purchases, Change chest type

  UI wiring only. Memory ops live in modules/ops/shop.lua.

  @module callback Receives container View to populate with modules
]]

local ops = CrashHandler.loadFeature("modules/ops/shop.lua")

return function(container)
    local function t(key, ...) return T("shop." .. key, ...) end

    addModule(container, "free_chest", t("free_chest.title"), t("free_chest.desc"), "switch", nil, function(done, state)
        ops.freeChest(state, function(status)
            showToast(t("free_chest." .. status), true)
        end)
        done()
    end)

    addModule(container, "free_purchases", t("free_purchases.title"), t("free_purchases.desc"), "button", nil, function(done)
        ops.freePurchases(
            function(counter, total) showToast(t("free_purchases.progress", counter, total), true) end,
            function(status)
                if status == "success" then gg.toast(t("free_purchases.success")) end
            end)
        done()
    end)

    addModule(container, "change_chest", t("change_chest.title"), t("change_chest.desc"), "spinner", {
        options = t("change_chest.options"),
        default = 8
    }, function(done, item, index)
        ops.changeChest(index, function()
            showToast(t("change_chest.changed", item))
        end)
        done()
    end)
end

end

__vfs['modules/tabs/status.lua'] = function(...)
--[[
  Status Tab - Live diagnostics (Script section, under Settings)

  Read-only snapshots of Nebula (version, metadata map, save/GameData
  channels), the game process (package, version, arch), and the memory
  section moved over from Settings. The Nebula probes do cheap single-field
  reads; the GameData probe resolves the GameData base on first open.

  @module callback Receives container View to populate with modules
]]

return function(container)
    local function t(key, ...) return T("status." .. key, ...) end

    -- ── Nebula ────────────────────────────────────────────────────────────────
    addModuleSep(container, t("section_nebula"))

    local nebVersion = (Nebula and Nebula.VERSION) or "not loaded"
    addModule(container, "nebula_version", t("nebula_version.title"),
        t("nebula_version.desc"), "ro", tostring(nebVersion), nil)

    local metaVersion = "unresolved"
    if Nebula and Nebula.PlayerInfo and Nebula.PlayerInfo.metadataVersion then
        local ok, v = pcall(Nebula.PlayerInfo.metadataVersion)
        if ok and v then metaVersion = tostring(v) end
    end
    addModule(container, "nebula_metadata", t("nebula_metadata.title"),
        t("nebula_metadata.desc"), "ro", metaVersion, nil)

    -- Save channel probe: one cheap Bool read proves PlayerInfo works.
    local saveProbe = "not loaded"
    if Nebula and Nebula.PlayerInfo then
        local ok, v = pcall(Nebula.PlayerInfo.get, "showHiddenVehicles")
        if not ok then
            saveProbe = "read failed"
        elseif v == nil then
            saveProbe = "unresolved"
        else
            saveProbe = "ok (Bool read: " .. tostring(v) .. ")"
        end
    end
    addModule(container, "nebula_save_probe", t("nebula_save_probe.title"),
        t("nebula_save_probe.desc"), "ro", saveProbe, nil)

    -- GameData channel probe: one Float read resolves the GameData base.
    local gdProbe = "not loaded"
    if Nebula and Nebula.GameData then
        local ok, v, err = pcall(Nebula.GameData.get, "startCountdown")
        if not ok or err then
            gdProbe = "read failed (" .. tostring(err or v) .. ")"
        elseif v == nil then
            gdProbe = "unresolved"
        else
            gdProbe = "ok (startCountdown: " .. tostring(v) .. "s)"
        end
    end
    addModule(container, "nebula_gamedata_probe", t("nebula_gamedata_probe.title"),
        t("nebula_gamedata_probe.desc"), "ro", gdProbe, nil)

    -- ── Game Process ──────────────────────────────────────────────────────────
    addModuleSep(container, t("section_process"))

    local info = gg.getTargetInfo() or {}

    addModule(container, "process_package", t("process_package.title"),
        t("process_package.desc"), "ro", tostring(info.packageName or "unknown"), nil)
    addModule(container, "process_version", t("process_version.title"),
        t("process_version.desc"), "ro", tostring(info.versionName or "unknown"), nil)
    addModule(container, "process_version_code", t("process_version_code.title"),
        t("process_version_code.desc"), "ro", tostring(info.versionCode or "unknown"), nil)
    addModule(container, "process_name", t("process_name.title"),
        t("process_name.desc"), "ro", tostring(info.processName or "unknown"), nil)
    addModule(container, "process_arch", t("process_arch.title"),
        t("process_arch.desc"), "ro",
        info.x64 and "64-bit" or "32-bit", nil)

    -- ── Memory ────────────────────────────────────────────────────────────────
    addModuleSep(container, t("section_memory"))

    local function regionName()
        if BaseRegion == -2080896 then return T("settings.region.other")
        elseif BaseRegion == 4 then return T("settings.region.cpp_alloc")
        else return T("settings.region.unknown") end
    end

    addModule(container, "memory_range", T("settings.memory_range.title"),
        T("settings.memory_range.desc"), "ro", regionName(), nil)
    addModule(container, "gamestatus_address", T("settings.gamestatus.title"),
        T("settings.gamestatus.desc"), "ro", string.format("0x%X", BaseGameStatus or 0), nil)

    addModule(container, "clear_memory", T("settings.clear_memory.title"),
        T("settings.clear_memory.desc"), "button", nil, function(done)
        LOG.info("Status", "User triggered clear_all()")
        storage:clear_all_session()
        showToast(t("clear_memory.done"), true)
        done()
    end)
end

end

__vfs['modules/tabs/team.lua'] = function(...)
--[[
  Team Tab - Team mode features
  Features: Team Size Bypass

  UI wiring only. Memory ops live in modules/ops/team.lua.
  done() is called right after dispatch (not inside the result callback) so a
  crash in the scheduled work can't leave a card stuck.

  @module callback Receives container View to populate with modules
]]

local ops = CrashHandler.loadFeature("modules/ops/team.lua")

return function(container)
    local function t(key, ...) return T("team." .. key, ...) end

    addModule(container, "team_size_bypass", t("team_size_bypass.title"),
        t("team_size_bypass.desc"), "switch", nil, function(done, state)
        ops.teamSizeBypass(state, function(status)
            showToast(t("team_size_bypass." .. status), true)
        end)
        done()
    end)

    -- "applied"/"reverted" toasts are per-card, everything else
    -- (resolve_failed | failed | nebula_unavailable | no_vehicles) is shared.
    local function epToast(card, status)
        if status == "applied" or status == "reverted" then
            showToast(t(card .. "." .. status))
        else
            showToast(t("ep." .. status), true)
        end
    end

    addModule(container, "unlimited_vehicle_usage", t("unlimited_vehicle_usage.title"),
        t("unlimited_vehicle_usage.desc"), "switch", nil, function(done, state)
        ops.unlimitedVehicleUsage(state, function(status)
            epToast("unlimited_vehicle_usage", status)
        end)
        done()
    end)

    addModule(container, "allow_all_vehicles", t("allow_all_vehicles.title"),
        t("allow_all_vehicles.desc"), "switch", nil, function(done, state)
        ops.allowAllVehicles(state, function(status)
            epToast("allow_all_vehicles", status)
        end)
        done()
    end)

    addModule(container, "free_entry_fee", t("free_entry_fee.title"),
        t("free_entry_fee.desc"), "switch", nil, function(done, state)
        ops.freeEntryFee(state, function(status)
            epToast("free_entry_fee", status)
        end)
        done()
    end)

    addModule(container, "vehicle_bonuses", t("vehicle_bonuses.title"),
        t("vehicle_bonuses.desc"), "switch", nil, function(done, state)
        ops.vehicleBonuses(state, function(status)
            epToast("vehicle_bonuses", status)
        end)
        done()
    end)

    addModule(container, "custom_participants", t("custom_participants.title"),
        t("custom_participants.desc"), "input", {
        { hint = t("custom_participants.hint"), value = "16", type = "number" },
    }, function(done, val)
        local n = math.floor(tonumber(val) or 0)
        if n < 1 then
            showToast(t("custom_participants.invalid"), true)
            done(); return
        end
        if n > 2147483647 then n = 2147483647 end
        if n > 100 then showToast(t("custom_participants.warn_big"), true) end
        ops.customParticipants(n, function(status)
            epToast("custom_participants", status)
        end)
        done()
    end)

    addModule(container, "custom_duration", t("custom_duration.title"),
        t("custom_duration.desc"), "input", {
        { hint = t("custom_duration.hint"), value = "300", type = "number" },
    }, function(done, val)
        local n = math.floor(tonumber(val) or 0)
        if n < 1 then
            showToast(t("custom_duration.invalid"), true)
            done(); return
        end
        if n > 2147483647 then n = 2147483647 end
        if n > 3600 then showToast(t("custom_duration.warn_big"), true) end
        ops.customDuration(n, function(status)
            epToast("custom_duration", status)
        end)
        done()
    end)

    addModule(container, "instant_ticket_refill", t("instant_ticket_refill.title"),
        t("instant_ticket_refill.desc"), "switch", nil, function(done, state)
        ops.instantTicketRefill(state, function(status)
            epToast("instant_ticket_refill", status)
        end)
        done()
    end)
end

end

__vfs['modules/tabs/vehicle.lua'] = function(...)
--[[
  Vehicle Tab - Vehicle modifications
  Features: Parts slot, Parts modifier, Fuel, Unlock vehicles, Max vehicles,
            Max mastery, Max parts, Tuning parts editors

  UI wiring only. Memory ops live in modules/ops/vehicle.lua.

  Note: done() is called right after dispatching each op (not inside the result
  callback) so a crash inside the scheduled work can never leave a card stuck
  in its "processing" state. The result callback only renders the outcome.

  @module callback Receives container View to populate with modules
]]

local ops  = CrashHandler.loadFeature("modules/ops/vehicle.lua")

-- "START BOOST" -> "Start Boost" for display only (internal keys stay as-is).
local function titleCase(s)
    return (tostring(s):lower():gsub("(%a)([%w']*)", function(a, b) return a:upper() .. b end))
end

return function(container)
    local function t(key, ...) return T("vehicle." .. key, ...) end

    addModule(container, "parts_slot", t("parts_slot.title"), t("parts_slot.desc"), "slider",
    {title=t("parts_slot.slider_title"), min=1, max=15, current=3},
    function(done, vals)
        ops.partsSlot(vals, function(status, count)
            if status == "no_vehicles" then
                showToast(t("common.no_vehicles"))
            elseif status == "no_zero_region" then
                showToast(t("common.no_zero_region"))
            else
                showToast(t("parts_slot.applied", count))
            end
        end)
        done()
    end)

    addArchModule(container, "parts_modifier", t("parts_modifier.title"), t("parts_modifier.desc"), "button", nil,
    function(done)
        local groupOrder, groupMap = ops.getPartGroups()

        -- Display list (Title Case); maps index back to raw label.
        local display = {}
        for i, lbl in ipairs(groupOrder) do display[i] = titleCase(lbl) end

        -- Builds the level float string from components.
        --   lvl=1, d0="0", d1="3" → "1.3"
        --   lvl=2, d0="0", d1="3" → "1.03"
        --   lvl=3, d0="0", d1="3" → "1.003"
        local function buildValue(lvl, d0, d1)
            local p = ""
            if lvl > 1 then for _ = 1, lvl - 1 do p = p .. d0 end end
            return "1." .. p .. d1
        end

        -- ── Depth-based navigation loop ───────────────────────────────────────
        -- depth 1 = part selection  (cancel → exit)
        -- depth 2 = stat selection  (cancel → back to depth 1; skipped if 1 stat)
        -- depth 3 = level prompt    (cancel → back to depth 2 or 1)
        --
        -- State preserved across depth transitions so going back restores the
        -- previous selection rather than resetting it.
        local depth     = 1
        local label, pretty, variants, statList, chosenStat, cacheKey

        while true do

            -- ── Depth 1: pick a part ─────────────────────────────────────────
            if depth == 1 then
                local choice = showList(t("parts_modifier.title"), t("parts_modifier.select"), display)
                if not choice or choice == 0 then
                    done(); return   -- top-level cancel → exit
                end
                label    = groupOrder[choice]
                pretty   = titleCase(label)
                variants = groupMap[label]
                statList = variants[1].statList

                -- If the part has only one stat there's nothing to pick —
                -- skip depth 2 and go straight to the level prompt.
                if #statList == 1 then
                    chosenStat = statList[1]
                    cacheKey   = "parts_mod_" .. label:lower():gsub(" ", "_")
                               .. "_" .. chosenStat.label:lower():gsub(" ", "_")
                    depth = 3
                else
                    depth = 2
                end

            -- ── Depth 2: pick a stat ─────────────────────────────────────────
            elseif depth == 2 then
                local statLabels = {}
                for _, s in ipairs(statList) do
                    statLabels[#statLabels + 1] = titleCase(s.label)
                end

                local statChoice = showList(pretty, t("parts_modifier.select_stat"), statLabels)
                if not statChoice or statChoice == 0 then
                    depth = 1   -- back to part selection
                else
                    chosenStat = statList[statChoice]
                    cacheKey   = "parts_mod_" .. label:lower():gsub(" ", "_")
                               .. "_" .. chosenStat.label:lower():gsub(" ", "_")
                    depth = 3
                end

            -- ── Depth 3: level prompt ─────────────────────────────────────────
            elseif depth == 3 then
                -- Show what was previously applied for this stat (if anything).
                local cached     = storage:load_session(cacheKey)
                local statusLine = cached
                    and t("parts_modifier.status_cached", #cached)
                    or  t("parts_modifier.status_none")

                local promptTitle = pretty .. ": " .. titleCase(chosenStat.label)
                                  .. "  (" .. statusLine .. ")"

                local result = showPrompt(promptTitle, {
                    {t("parts_modifier.prompt_level"),  "slider:1:9", "2"},
                    {t("parts_modifier.prompt_digit0"), "slider:0:9", "0"},
                    {t("parts_modifier.prompt_digit1"), "slider:1:9", "3"},
                    {t("parts_modifier.prompt_reset"),  "checkbox",   "false"},
                })

                if not result then
                    -- Back: if we skipped depth 2 (single-stat part) go to 1,
                    -- otherwise go to 2.
                    depth = (#statList == 1) and 1 or 2
                else
                    local reset  = result[4] == "true"
                    local lvl    = tonumber(result[1]) or 2
                    local digit0 = tostring(result[2] or "0")
                    local digit1 = tostring(result[3] or "3")
                    local userEdits = buildValue(lvl, digit0, digit1)
                    local editValue = tonumber(userEdits)

                    if not reset and not editValue then
                        showToast(t("parts_modifier.invalid"), true)
                        -- Stay at depth 3 — let user try again without losing context
                    else
                        ops.applyPartsModifier({
                            variants   = variants,
                            chosenStat = chosenStat,
                            cacheKey   = cacheKey,
                            editValue  = editValue,
                            reset      = reset,
                        }, function(status)
                            if status == "not_found" then
                                showToast(t("parts_modifier.not_found"), true)
                            elseif status == "reset" then
                                showToast(t("parts_modifier.reset", pretty), true)
                            else
                                showToast(t("parts_modifier.applied",
                                    pretty .. " " .. titleCase(chosenStat.label), userEdits), true)
                            end
                        end)
                        done(); return
                    end
                end
            end

        end -- while true
    end)

    addArchModule(container, "fuel", t("fuel.title"), t("fuel.desc"), "button", nil, function(done)
        local input = showPrompt(t("fuel.title"), {
            {t("fuel.prompt_amount"), "number", "50"},
            {t("fuel.prompt_reset"),  "checkbox", "false"},
        })

        if not input then
            done()
            return
        end

        ops.setFuel({ amount = input[1], reset = input[2] == "true" }, function(status, val)
            if status == "not_applied" then
                showToast(t("fuel.not_applied"), true)
            elseif status == "invalid" then
                showToast(t("fuel.invalid"), true)
            elseif status == "reset" then
                showToast(t("fuel.reset"), true)
            else
                showToast(t("fuel.applied", val), true)
            end
        end)
        done()
    end)

    addModule(container, "unlock_vehicles", t("unlock_vehicles.title"), t("unlock_vehicles.desc"), "button", nil,
    function(done)
        ops.unlockVehicles(function(status, count)
            if status == "no_vehicles" then
                showToast(t("common.no_vehicles"))
            elseif status == "unlocked" then
                showToast(t("unlock_vehicles.unlocked", count))
            else
                showToast(t("unlock_vehicles.none_to_unlock"))
            end
        end)
        done()
    end)

    addModule(container, "max_vehicles", t("max_vehicles.title"), t("max_vehicles.desc"), "button", nil,
    function(done)
        ops.maxVehicles(
            function(i, total) showToast(t("common.progress", i, total), true) end,
            function(status, stats)
                if status == "no_vehicles" then
                    showToast(t("max_vehicles.no_vehicles"))
                elseif status == "all_maxed" then
                    showToast(t("max_vehicles.applied", stats.written, stats.upgrades, stats.vehicles))
                else
                    showToast(t("max_vehicles.failed"))
                end
            end)
        done()
    end)

    addModule(container, "max_mastery", t("max_mastery.title"), t("max_mastery.desc"), "button", nil,
    function(done)
        ops.maxMastery(
            function(i, total) showToast(t("common.progress", i, total), true) end,
            function(status)
                showToast(status == "all_maxed" and t("max_mastery.all_maxed") or t("max_mastery.failed"))
            end)
        done()
    end)

    addModule(container, "max_parts", t("max_parts.title"), t("max_parts.desc"), "button", nil,
    function(done)
        ops.maxParts(
            function(i, total) showToast(t("common.progress", i, total), true) end,
            function(status, stats)
                if status == "no_vehicles" then
                    showToast(t("max_parts.no_vehicles"))
                elseif status == "all_maxed" then
                    showToast(t("max_parts.applied", stats.written, stats.parts, stats.vehicles))
                else
                    showToast(t("max_parts.failed"))
                end
            end)
        done()
    end)

    -- ── Per-slot parts editor (shared by both tuning editors) ─────────────
    -- One row per filled slot plus an "Add a part" row. Tapping a row opens a
    -- single-choice picker (swap or remove that slot's part); the slot list
    -- then re-opens showing the new state. Closing the list finishes.
    -- Edits stay in memory while the list is open; the single write
    -- happens once the user closes the list (per-action writes made
    -- the prompt feel laggy).
    local function slotEditor(title, hint, ids, parts, writeFn)
        local partDisp, dispToId = {}, {}
        for _, part in ipairs(parts) do
            local d = part.id .. " (" .. part.level .. "/" .. part.maxLevel .. ")"
            partDisp[#partDisp + 1] = d
            dispToId[d] = part.id
        end

        local MAX_SLOTS = 15

        local orig = {}
        for i, id in ipairs(ids) do orig[i] = id end

        while true do
            local labels = {}
            for i, id in ipairs(ids) do
                labels[#labels + 1] = (id ~= "" and id)
                    and t("slot.filled", i, id)
                    or  t("slot.empty", i)
            end
            if #ids < MAX_SLOTS then
                labels[#labels + 1] = t("slot.add")
            end

            local pick = showList(title, hint, labels)
            if not pick or pick == 0 then
                -- Closed: flush once if anything changed.
                local changed = #orig ~= #ids
                if not changed then
                    for i = 1, #orig do
                        if orig[i] ~= ids[i] then changed = true; break end
                    end
                end
                if changed then
                    writeFn(ids, function(ok)
                        if ok then
                            showToast(t("slot.saved"))
                        else
                            for i = 1, #orig do ids[i] = orig[i] end
                            for i = #orig + 1, #ids do ids[i] = nil end
                            showToast(t("slot.write_failed"), true)
                        end
                    end)
                end
                break
            end

            if pick > #ids then
                -- Add row: any owned part, even one already in another
                -- slot (duplicates are allowed).
                local opts, optIds = {}, {}
                for _, d in ipairs(partDisp) do
                    opts[#opts + 1] = d
                    optIds[#optIds + 1] = dispToId[d]
                end
                if #opts == 0 then
                    showToast(t("slot.none_free"), true)
                else
                    local c = showList(t("slot.add_title"), t("slot.pick_part"), opts)
                    if c and c > 0 then
                        table.insert(ids, optIds[c])
                    end
                end
            else
                local slot = pick
                local cur = ids[slot]
                -- Picker: remove option first, then every owned part.
                -- Duplicates are allowed: the same part can sit in several slots.
                local opts, optIds = {}, {}
                opts[#opts + 1] = t("slot.remove"); optIds[#optIds + 1] = nil
                for _, d in ipairs(partDisp) do
                    opts[#opts + 1] = d
                    optIds[#optIds + 1] = dispToId[d]
                end

                local c = showList(t("slot.pick_title", slot), t("slot.pick_part"), opts)
                if c and c > 1 then
                    ids[slot] = optIds[c]
                elseif c == 1 then
                    table.remove(ids, slot)
                end
            end
        end
    end

    -- ── Equipped Tuning Parts editor (Nebula) ─────────────────────────────
    addModule(container, "show_hidden", t("show_hidden.title"), t("show_hidden.desc"), "switch", nil,
    function(done, state)
        ops.showHiddenVehicles(state, function(status)
            if status == "applied" then
                showToast(t("show_hidden.applied"), true)
            elseif status == "reverted" then
                showToast(t("show_hidden.reverted"), true)
            elseif status == "nebula_unavailable" then
                showToast(T("common.nebula_unavailable"))
            else
                showToast(t("show_hidden.failed"))
            end
        end)
        done()
    end)

    addModule(container, "tuning_equipped", t("tuning_equipped.title"), t("tuning_equipped.desc"), "button", nil,
    function(done)
        ops.listVehicles(function(status, vehicles)
            if status ~= "ok" then
                if status == "no_vehicles" then
                    showToast(t("common.no_vehicles"))
                elseif status == "nebula_unavailable" then
                    showToast(t("common.nebula_unavailable"), true)
                else
                    showToast(t("tuning_equipped.failed"), true)
                end
                return
            end

            local names, byName = {}, {}
            for _, v in ipairs(vehicles) do
                names[#names + 1] = v.id
                byName[v.id] = v.index
            end

            local pick = showList(t("tuning_equipped.pick_vehicle"), t("tuning_equipped.pick_vehicle_desc"), names)
            if not pick or pick == 0 then return end
            local vIdx = byName[names[pick]]

            ops.listParts(vIdx, function(pStatus, parts)
                if pStatus ~= "ok" then
                    showToast(pStatus == "no_parts" and t("tuning_equipped.no_parts") or t("tuning_equipped.failed"), true)
                    return
                end

                ops.getEquipped(vIdx, function(eStatus, equipped)
                    if eStatus ~= "ok" then
                        showToast(t("tuning_equipped.failed"), true)
                        return
                    end

                    local ids = {}
                    for _, id in ipairs(equipped) do ids[#ids + 1] = id end

                    slotEditor(t("tuning_equipped.title"), t("tuning_equipped.hint"), ids, parts,
                        function(newIds, onDone)
                            ops.setEquipped(vIdx, newIds, function(sStatus)
                                onDone(sStatus == "applied")
                            end)
                        end)
                end)
            end)
        end)
        done()
    end)

    -- ── Tuning Part Presets editor (Nebula) ────────────────────────────────
    addModule(container, "tuning_presets", t("tuning_presets.title"), t("tuning_presets.desc"), "button", nil,
    function(done)
        ops.listVehicles(function(status, vehicles)
            if status ~= "ok" then
                if status == "no_vehicles" then
                    showToast(t("common.no_vehicles"))
                elseif status == "nebula_unavailable" then
                    showToast(t("common.nebula_unavailable"), true)
                else
                    showToast(t("tuning_presets.failed"), true)
                end
                return
            end

            local names, byName = {}, {}
            for _, v in ipairs(vehicles) do
                names[#names + 1] = v.id
                byName[v.id] = v.index
            end

            local pick = showList(t("tuning_presets.pick_vehicle"), t("tuning_presets.pick_vehicle_desc"), names)
            if not pick or pick == 0 then return end
            local vIdx = byName[names[pick]]

            local function openPresetList()
                ops.listPresets(vIdx, function(psStatus, presets, selected)
                    if psStatus ~= "ok" then
                        showToast(psStatus == "no_presets" and t("tuning_presets.no_presets") or t("tuning_presets.failed"), true)
                        return
                    end

                    local labels = {}
                    for _, pr in ipairs(presets) do
                        local partsStr = #pr.parts > 0
                            and table.concat(pr.parts, ", ")
                            or  t("tuning_presets.preset_empty")
                        local lbl = t("tuning_presets.preset_label", pr.index, partsStr)
                        if pr.index == selected then lbl = lbl .. " (" .. t("tuning_presets.active") .. ")" end
                        labels[#labels + 1] = lbl
                    end
                    labels[#labels + 1] = t("tuning_presets.add")

                    local pPick = showList(t("tuning_presets.title"), t("tuning_presets.pick_preset_desc"), labels)
                    if not pPick or pPick == 0 then return end

                    -- "+ Add Preset" row: append an empty preset and reopen.
                    if pPick > #presets then
                        ops.addPreset(vIdx, function(aStatus, count)
                            if aStatus == "applied" then
                                showToast(t("tuning_presets.added", count), true)
                                openPresetList()
                            elseif aStatus == "max_reached" then
                                showToast(t("tuning_presets.max_reached"), true)
                            else
                                showToast(t("tuning_presets.failed"), true)
                            end
                        end)
                        return
                    end

                    local pIdx = presets[pPick].index

                        local actions = {
                        t("tuning_presets.action_edit"),
                        t("tuning_presets.action_activate"),
                        t("tuning_presets.action_copy_current"),
                    }
                    local aPick = showList(labels[pPick], t("tuning_presets.pick_action"), actions)
                    if not aPick or aPick == 0 then return end

                    if aPick == 1 then
                        -- Per-slot edit of this preset's parts.
                        ops.listParts(vIdx, function(lStatus, parts)
                            if lStatus ~= "ok" then
                                showToast(t("tuning_equipped.no_parts"), true)
                                return
                            end

                            local ids = {}
                            for _, pr in ipairs(presets) do
                                if pr.index == pIdx then
                                    for _, id in ipairs(pr.parts) do ids[#ids + 1] = id end
                                    break
                                end
                            end

                            slotEditor(labels[pPick], t("tuning_presets.hint"), ids, parts,
                                function(newIds, onDone)
                                    ops.setPresetParts(vIdx, pIdx, newIds, function(sStatus)
                                        onDone(sStatus == "applied")
                                    end)
                                end)
                        end)
                    elseif aPick == 2 then
                        ops.setSelectedPreset(vIdx, pIdx, function(sStatus)
                            if sStatus == "applied" then
                                showToast(t("tuning_presets.activated", pIdx), true)
                            else
                                showToast(t("tuning_presets.failed"), true)
                            end
                        end)
                    else
                        ops.saveEquippedToPreset(vIdx, pIdx, function(sStatus, count)
                            if sStatus == "applied" then
                                showToast(t("tuning_presets.copied", pIdx, count), true)
                            elseif sStatus == "not_equipped" then
                                showToast(t("tuning_presets.nothing_equipped"), true)
                            else
                                showToast(t("tuning_presets.failed"), true)
                            end
                        end)
                    end
                end)
            end
            openPresetList()
        end)
        done()
    end)
end
end

__vfs['ui/ui.lua'] = function(...)
--[[
  UI Module — Interface management and component builder.
  Creates and manages all UI elements: tabs, module cards, dialogs, animations.

  Dependencies: All Android imports from main.lua, UI constants, helper functions.
  Exports: loadCategory, addTab, addModule, updateRO, createIconView, createMenuView, initUI
]]


-- ─────────────────────────────────────────────────────────────────────────────
-- HELPERS
-- ─────────────────────────────────────────────────────────────────────────────

-- RTL language codes. Layout direction is flipped for these so the sidebar
-- appears on the right and text flows right-to-left.
local RTL_CODES = { ar = true, ur = true, he = true, fa = true }

-- Returns true when the active language is right-to-left.
local function isRTL()
    return RTL_CODES[LANG_CODE] == true
end

-- Resolves the correct Gravity constant for start-of-line alignment,
-- accounting for RTL layout direction.
local function gravityStart()
    return isRTL() and Gravity.RIGHT or Gravity.LEFT
end

-- Resolves the correct Gravity constant for end-of-line alignment.
local function gravityEnd()
    return isRTL() and Gravity.LEFT or Gravity.RIGHT
end


-- Sets layout direction on a view so Android mirrors padding and drawables.
-- API 17+; silently skipped on older devices.
function setLayoutDir(view)
    if Build.VERSION.SDK_INT >= 17 then
        local dir = isRTL() and 1 or 0  -- LAYOUT_DIRECTION_RTL = 1, LTR = 0
        view.setLayoutDirection(dir)
    end
end


-- ─────────────────────────────────────────────────────────────────────────────
-- CATEGORY MANAGEMENT
-- ─────────────────────────────────────────────────────────────────────────────

-- Sidebar tab registry: id → { container, iconTV, labelTV }
-- Keyed by tab id string so loadCategory can recolor children without
-- relying on Java object equality as table keys.
local _tabData     = {}
local _activeTabId = nil

-- ── Global search state ──────────────────────────────────────────────────────
-- VOID_MODULE_INDEX is populated by addModule() at render time (id →
-- { title, desc, tabId, tabName }); VOID_CURRENT_TAB/NAME are set by
-- loadCategory() and by the background cache warm-up so registrations
-- know which tab they belong to. _searchBox/_searchActive manage the
-- search bar's interaction with loadCategory.
VOID_MODULE_INDEX     = {}
VOID_CURRENT_TAB      = nil
VOID_CURRENT_TAB_NAME = nil
local _searchBox     = nil
local _searchActive  = false

-- Per-tab rendered view-tree cache: id → LinearLayout already populated by
-- that tab's render function. On revisit we just swap this cached subtree
-- back into moduleContainer instead of clearing+re-running the render
-- function, which used to recreate every card's Java views from scratch on
-- every single tab switch. Reset alongside _tabData whenever the menu is
-- rebuilt from scratch (see _buildMenuTabs), since a full rebuild gets a
-- fresh moduleContainer anyway.
local _tabContentCache = {}

-- Animated "Loading..." indicator shown while a tab's content is being
-- built for the first time. Returns the view plus a stop() closure so the
-- caller can halt the postDelayed loop once real content is ready, rather
-- than leaving it ticking on a detached view.
--@return View spinner, fun() stop
local _LOADING_DOTS = { "", ".", "..", "..." }
-- Hard ceiling on ticks as a last-resort safety net: 600 * 350ms ≈ 3.5 minutes,
-- far beyond any real tab render. If something forgets to call stop() this
-- guarantees the loop still dies instead of ticking forever.
local _SPINNER_MAX_TICKS = 600
local function _createLoadingSpinner()
    local spinner = TextView(activity)
    spinner.setTextColor(UI.SUB)
    spinner.setTextSize(1, 11)
    spinner.setGravity(Gravity.CENTER)
    spinner.setLayoutParams(LinLayoutParams(-1, dp(60)))

    local state = { running = true, frame = 0, ticks = 0 }

    -- Auto-stop if the view itself gets detached (tab switched away / menu
    -- closed) — this covers the case even when the caller never calls stop()
    -- on that code path.
    spinner.addOnAttachStateChangeListener(View.OnAttachStateChangeListener({
        onViewAttachedToWindow = function(v) end,
        onViewDetachedFromWindow = function(v) state.running = false end
    }))

    local function tick()
        if not state.running then return end
        state.ticks = state.ticks + 1
        if state.ticks > _SPINNER_MAX_TICKS then
            state.running = false
            return
        end
        state.frame = (state.frame % #_LOADING_DOTS) + 1
        spinner.setText(T("ui.loading") .. _LOADING_DOTS[state.frame])
        spinner.postDelayed(function() tick() end, 350)
    end
    tick()

    return spinner, function() state.running = false end
end

-- Loads and displays a category (tab content) by ID.
-- Updates active tab styling and populates moduleContainer with category modules.
-- Cached tabs swap in instantly; uncached tabs show an animated loading
-- indicator and render on the next MainHandler frame so the UI thread stays
-- Loads and displays a category (tab content) by ID.
-- Updates active tab styling and populates moduleContainer with category modules.
-- Cached tabs swap in instantly; uncached tabs show an animated loading
-- indicator and render on the next MainHandler frame so the UI thread stays
-- responsive even when a tab has dozens of cards.
--@param id string  Tab identifier to load
--@param tabView View  The tab container that was clicked
--@return nil
function loadCategory(id, tabView)
    LOG.info("loadCategory", "id=" .. tostring(id))
    if not moduleContainer or not tabView then
        LOG.warn("loadCategory", "EARLY RETURN — moduleContainer=" .. tostring(moduleContainer) .. " tabView=" .. tostring(tabView))
        return
    end

    -- Swap active tab styling immediately (zero Java work — just background + colors).
    if _activeTabId and _tabData[_activeTabId] then
        local prev = _tabData[_activeTabId]
        prev.container.setBackground(getSkin(UI.BG, 8))
        prev.iconTV.setTextColor(UI.SUB)
        prev.labelTV.setTextColor(UI.SUB)
    end
    if _tabData[id] then
        local curr = _tabData[id]
        curr.container.setBackground(getSkin(UI.ACCENT, 8))
        curr.iconTV.setTextColor(UI.TEXT)
        curr.labelTV.setTextColor(UI.TEXT)
    end

    _activeTabId  = id
    activeTabView = tabView
    VOID_CURRENT_TAB, VOID_CURRENT_TAB_NAME = id, id

    -- Any tab switch leaves search mode; clear the box silently (the
    -- TextWatcher sees the now-empty query and skips a re-render because
    -- _searchActive is already false) and restore the window's NOT_FOCUSABLE
    -- flags in case the search box still held focus.
    if _searchActive then
        _searchActive = false
        if _searchBox then _searchBox.setText("") end
        if menuView and mParams.flags ~= (8 | 32) then
            pcall(function()
                mParams.flags = 8 | 32
                windowManager.updateViewLayout(menuView, mParams)
            end)
        end
    end

    moduleContainer.removeAllViews()

    -- Already built — instant swap, no Java view recreation at all.
    -- The Console tab is never cached so it always reflects the latest reports.
    if _tabContentCache[id] and id ~= "console" then
        moduleContainer.addView(_tabContentCache[id])
        return
    end

    -- Not cached yet: show the animated spinner, defer the (potentially
    -- expensive) module render to the next frame so the tap response stays
    -- instant, then cache the resulting view tree for next time.
    local spinner, stopSpinner = _createLoadingSpinner()
    moduleContainer.addView(spinner)

    local setCategory = categoryHandlers[id]
    MainHandler.post(Runnable({ run = function()
        stopSpinner()
        moduleContainer.removeAllViews()

        local tabContent = LinearLayout(activity)
        tabContent.setOrientation(1)
        tabContent.setLayoutParams(LinLayoutParams(-1, -2))

        if setCategory then
            local ok, err = pcall(function() setCategory(tabContent) end)
            if ok then
                -- Only cache on success — a failed render should retry next time.
                -- Console is intentionally left uncached (always re-rendered).
                if id ~= "console" then _tabContentCache[id] = tabContent end
            else
                local errTxt = TextView(activity)
                errTxt.setText(T("ui.category_error", tostring(err)))
                errTxt.setTextColor(UI.RED)
                tabContent.addView(errTxt)
            end
        else
            local errTxt = TextView(activity)
            errTxt.setText(T("ui.category_not_found"))
            errTxt.setTextColor(UI.SUB)
            tabContent.addView(errTxt)
        end

        -- Bail out if the user already switched to a different tab while
        -- this frame was queued — don't stomp whatever is now showing.
        if _activeTabId ~= id then return end
        moduleContainer.removeAllViews()
        moduleContainer.addView(tabContent)
    end }))
end


-- ─────────────────────────────────────────────────────────────────────────────
-- TAB BUILDER
-- ─────────────────────────────────────────────────────────────────────────────

-- Unicode icon map keyed by tab id.
-- Basic BMP characters that render on all Android versions.
local _TAB_ICONS = {
    account   = "\xe2\x8a\x99",  -- ⊙  profile/user
    player    = "\xe2\x96\xb7",  -- ▷  play/game
    vehicle   = "\xe2\x96\xb6",  -- ▶  vehicle
    adventure = "\xe2\x97\x86",  -- ◆  quest/adventure
    cups      = "\xe2\x96\xb2",  -- ▲  trophy/cups
    team      = "\xe2\x8a\x9e",  -- ⊞  grid/team
    event     = "\xe2\x96\xa3",  -- ▣  calendar/event
    creative  = "\xe2\x98\x85",  -- ★  star/creative
    shop      = "\xe2\x97\x91",  -- ◑  coin/shop
    other     = "\xe2\x8b\xaf",  -- ⋯  ellipsis/other
    settings  = "\xe2\x9a\x99",  -- ⚙  gear/settings
    status    = "\xe2\x97\x88",  -- ◈  status/diagnostics
    about     = "\xe2\x84\xb9",  -- ℹ  info/about
    console   = "\xe2\x9a\xa0",  -- ⚠  warning/console
}

-- Creates a sidebar tab row (icon + label) that loads a category when tapped.
-- Registers icon+label refs in _tabData[id] for later recoloring by loadCategory.
-- In RTL mode the row is reversed (label on left, icon on right).
--@param parent View  Layout to add the tab to
--@param id string  Tab identifier
--@param name string  Display label
--@return View  The created tab container
function addTab(parent, id, name)
    local icon_char = UI.TABS_ICON or (_TAB_ICONS[id] or "•")

    local container = LinearLayout(activity)
    container.setOrientation(0)
    setLayoutDir(container)
    local params = LinLayoutParams(-1, -2)
    params.bottomMargin = dp(2)
    container.setLayoutParams(params)
    container.setPadding(dp(8), dp(8), dp(6), dp(8))
    container.setGravity(Gravity.CENTER_VERTICAL)
    container.setBackground(getSkin(UI.BG, 8))

    -- Icon
    local iconTV = TextView(activity)
    local iconParams = LinLayoutParams(dp(20), dp(20))
    if isRTL() then
        iconParams.leftMargin = dp(7)
    else
        iconParams.rightMargin = dp(7)
    end
    iconTV.setLayoutParams(iconParams)
    iconTV.setText(icon_char)
    iconTV.setTextColor(UI.SUB)
    iconTV.setTextSize(1, 13)
    iconTV.setGravity(Gravity.CENTER)
    iconTV.setTypeface(Typeface.DEFAULT_BOLD)

    -- Label
    local labelTV = TextView(activity)
    labelTV.setLayoutParams(LinLayoutParams(0, -2, 1.0))
    labelTV.setText(tostring(name))
    labelTV.setTextColor(UI.SUB)
    labelTV.setTextSize(1, 9)
    labelTV.setTypeface(Typeface.create("sans-serif", Typeface.BOLD))
    labelTV.setSingleLine(false)
    labelTV.setMaxLines(2)
    if isRTL() then
        labelTV.setGravity(Gravity.RIGHT)
        -- RTL: label first, then icon
        container.addView(labelTV)
        container.addView(iconTV)
    else
        container.addView(iconTV)
        container.addView(labelTV)
    end

    container.setOnClickListener(View.OnClickListener({
        onClick = function(v) loadCategory(id, container) end
    }))

    _tabData[id] = { container = container, iconTV = iconTV, labelTV = labelTV }
    parent.addView(container)
    return container
end


-- ─────────────────────────────────────────────────────────────────────────────
-- MODULE CARD BUILDER
-- ─────────────────────────────────────────────────────────────────────────────

-- Creates an interactive module card with various modes.
--
-- Mode descriptions:
--   "switch"  — Toggle on/off (state saved)
--   "button"  — Single action button
--   "ro"      — Read-only display (clickable to copy)
--   "spinner" — Dropdown selector (state saved)
--   "slider"  — Single or multi-slider input (state saved)
--   "input"   — Single or multi-line text input (state saved)
--   nil       — Plain info card: title+desc only, no action widget at all.
--              For content that's just meant to be read (e.g. About tab),
--              not a value anyone needs to toggle/copy/configure.
--
--@param parent View  Container to add the card to
--@param id string  Unique module identifier
--@param title string  Display title
--@param desc string  Description text
--@param mode string?  "switch" | "button" | "ro" | "spinner" | "slider" | "input" | nil
--@param extra any  Mode-specific data
--@param callback? fun(done:fun(), ...)  Called on action; must call done() when finished
--@return nil

-- Renders text into a TextView, turning markdown links [label](url) into
-- tappable links that open in the browser. If the text has no links (or the
-- rich-text path errors on this device) it falls back to plain setText.
local function setRichText(tv, text, linkColor)
    text = tostring(text or "")
    if not text:find("%[.-%]%(.-%)") then
        tv.setText(text)
        return
    end
    local ok = pcall(function()
        local function esc(s) return (s:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")) end
        local html = esc(text):gsub("%[(.-)%]%((.-)%)", function(label, url)
            return '<a href="' .. url:gsub("&amp;", "&") .. '">' .. label .. '</a>'
        end)
        html = html:gsub("\n", "<br>")
        local spanned = (Build.VERSION.SDK_INT >= 24) and Html.fromHtml(html, 0) or Html.fromHtml(html)
        tv.setText(spanned)
        tv.setMovementMethod(LinkMovementMethod.getInstance())
        if linkColor then tv.setLinkTextColor(linkColor) end
    end)
    if not ok then tv.setText(text) end
end

-- Long/multi-line "ro" values (e.g. multi-paragraph about/credits text) must
-- never be rendered verbatim inside the compact copy-chip: with no width
-- bound a long value blows up topRow's layout and squeezes the title+desc
-- text out of view entirely. This truncates the CHIP'S DISPLAY text only —
-- callers always get the full original value back via RO_RawValues for
-- copy-to-clipboard.
local function _roDisplayText(rawVal)
    local firstLine = rawVal:match("^[^\n]*") or rawVal
    if #firstLine > 40 or firstLine ~= rawVal then
        return firstLine:sub(1, 40) .. "…"
    end
    return rawVal
end

currentInputs = {}
--==================================================
-- Risk badge (per-card risk level pill)
--==================================================

-- Builds the small colored pill shown on cards with a risk level
-- (registry: configs/app/risk.lua, colors: UI.RISK). Tapping it opens a
-- dialog explaining what the level means. Returns nil when the card
-- has no risk level assigned.
function buildRiskPill(id, level)
    local def = UI.RISK and UI.RISK[level:upper()]
    if not def then return nil end

    local pill = TextView(activity)
    pill.setText(T("risk." .. level))
    pill.setTextColor(def.TEXT)
    pill.setTextSize(1, 8)
    pill.setTypeface(Typeface.create("sans-serif-medium", Typeface.BOLD))
    pill.setPadding(dp(6), dp(2), dp(6), dp(2))
    pill.setBackground(getSkin(def.BG, 8, 1, def.TEXT))
    local lp = LinLayoutParams(-2, -2)
    lp.leftMargin  = dp(4)
    lp.rightMargin = dp(4)
    pill.setLayoutParams(lp)
    pill.setOnClickListener(View.OnClickListener({ onClick = function()
        showDialog(T("risk.title"), T("risk." .. level .. ".info"), T("common.ok"))
    end }))
    return pill
end

-- Release-channel badge next to the VOID title (menu header + icon pill).
-- Text/color come from RELEASE_CHANNEL (main.lua) and UI.CHANNEL.
function buildChannelBadge()
    if not RELEASE_CHANNEL then return nil end
    local def = UI.CHANNEL and UI.CHANNEL[RELEASE_CHANNEL]
    local b = TextView(activity)
    b.setText(RELEASE_CHANNEL)
    b.setTextColor(def and def.TEXT or UI.SUB)
    b.setTextSize(1, 8)
    b.setTypeface(Typeface.create("sans-serif-medium", Typeface.BOLD))
    b.setPadding(dp(6), dp(2), dp(6), dp(2))
    b.setBackground(getSkin(def and def.BG or UI.MUTED, 8, 1, def and def.TEXT or UI.STROKE))
    local lp = LinLayoutParams(-2, -2)
    lp.leftMargin  = dp(6)
    lp.rightMargin = dp(2)
    b.setLayoutParams(lp)
    return b
end

function addModule(parent, id, title, desc, mode, extra, callback, opts)
    -- Risk level: opts.risk wins, otherwise the configs/app/risk.lua registry.
    local riskLevel = (opts and opts.risk) or (VOID_RISK and VOID_RISK[id]) or nil

    if processingStates[id] == nil then processingStates[id] = false end
    if toggleStates[id]     == nil then toggleStates[id]     = false end
    if lastClickTimes[id]   == nil then lastClickTimes[id]   = 0     end

    local card = LinearLayout(activity)
    local cp = LinLayoutParams(-1, -2)
    cp.bottomMargin = dp(10)
    card.setLayoutParams(cp)
    card.setOrientation(1)
    card.setPadding(dp(15), dp(12), dp(15), dp(12))
    card.setBackground(getSkin(UI.CARD, 12, 1, UI.STROKE))
    card.setAlpha(1.0)
    setLayoutDir(card)

    -- Register in the global search index + tag the card view so search
    -- results can scroll to it inside the cached tab content.
    VOID_MODULE_INDEX[id] = {
        title   = tostring(title),
        desc    = tostring(desc),
        tabId   = VOID_CURRENT_TAB,
        tabName = VOID_CURRENT_TAB_NAME,
    }
    pcall(function() card.setTag(id) end)

    -- Debounce + visual feedback wrapper around user callbacks.
    local function safeCallback(...)
        local args = {...}
        local now = os.clock() * 1000
        if processingStates[id] or (now - lastClickTimes[id] < CLICK_COOLDOWN) then return end

        lastClickTimes[id]   = now
        processingStates[id] = true

        card.setBackground(getSkin(UI.ACCENT, 12, 1, UI.STROKE))
        card.setAlpha(0.25)

        local function done()
            MainHandler.post(Runnable({ run = function()
                processingStates[id] = false
                card.setBackground(getSkin(UI.CARD, 12, 1, UI.STROKE))
                card.setAlpha(1.0)
            end }))
        end

        Thread(Runnable({ run = function()
            if callback then
                local tb
                local ok, err = xpcall(
                    function() callback(done, table.unpack(args)) end,
                    function(e)
                        tb = (debug and debug.traceback) and debug.traceback(tostring(e), 2) or tostring(e)
                        return e
                    end)
                storage:save_session("toggle_states",  toggleStates)
                storage:save_session("input_states",   inputStates)
                storage:save_session("spinner_states", spinnerStates)
                storage:save_session("slider_states",  sliderStates)
                if not ok then
                    -- Capture so the failure surfaces in the Console tab; the
                    -- scheduler only sees crashes inside scheduler:add, not the
                    -- synchronous part of a module callback.
                    if CrashHandler then
                        CrashHandler.capture("Module:" .. tostring(id), err, tb)
                    else
                        print("Error in callback: " .. tostring(err))
                    end
                    done()
                end
            else
                Thread.sleep(CLICK_COOLDOWN)
                done()
            end
        end })).start()
    end

    -- Top row: title+desc on the left (or right for RTL), action widget on the other side.
    local topRow = LinearLayout(activity)
    topRow.setOrientation(0)
    topRow.setGravity(Gravity.CENTER_VERTICAL)
    setLayoutDir(topRow)

    local textLayout = LinearLayout(activity)
    textLayout.setLayoutParams(LinLayoutParams(0, -2, 1.0))
    textLayout.setOrientation(1)

    local t1 = TextView(activity)
    t1.setText(title)
    t1.setTextColor(UI.TEXT)
    t1.setTextSize(1, 14)
    t1.setTypeface(Typeface.create("sans-serif-medium", Typeface.BOLD))
    -- Hug the title text (no weight), but cap it so a long title truncates
    -- instead of pushing the risk pill out of the card.
    t1.setSingleLine(true)
    t1.setEllipsize(TruncateAt.END)
    t1.setMaxWidth(dp(190))
    if isRTL() then t1.setGravity(Gravity.RIGHT) end

    -- Title row: title (hugged, width-capped) + pill right after it + a
    -- weight-1 spacer that absorbs the remaining space.
    local titleRow = LinearLayout(activity)
    titleRow.setOrientation(0)
    titleRow.setGravity(Gravity.CENTER_VERTICAL)
    setLayoutDir(titleRow)
    titleRow.setLayoutParams(LinLayoutParams(-1, -2))

    titleRow.addView(t1)
    if riskLevel then
        local rp = buildRiskPill(id, riskLevel)
        if rp then titleRow.addView(rp) end
    end
    local titleSpacer = View(activity)
    titleSpacer.setLayoutParams(LinLayoutParams(0, 1, 1.0))
    titleRow.addView(titleSpacer)

    local t2 = TextView(activity)
    setRichText(t2, desc, UI.LOGO)
    t2.setTextColor(UI.SUB)
    t2.setTextSize(1, 10)
    if isRTL() then t2.setGravity(Gravity.RIGHT) end

    textLayout.addView(titleRow)
    textLayout.addView(t2)
    topRow.addView(textLayout)

    local actionArea = LinearLayout(activity)
    actionArea.setGravity(gravityEnd() | Gravity.CENTER_VERTICAL)

    if mode == "switch" then
        local sw = TextView(activity)
        sw.setLayoutParams(LinLayoutParams(dp(36), dp(18)))
        local function updateSw()
            sw.setBackground(getSkin(toggleStates[id] and UI.ACCENT or UI.MUTED, 20))
        end
        updateSw()
        card.setOnClickListener(View.OnClickListener({ onClick = function()
            local now = os.clock() * 1000
            if processingStates[id] or (now - lastClickTimes[id] < CLICK_COOLDOWN) then return end
            toggleStates[id] = not toggleStates[id]
            updateSw()
            safeCallback(toggleStates[id])
        end }))
        actionArea.addView(sw)

    elseif mode == "button" then
        local btn = TextView(activity)
        btn.setLayoutParams(LinLayoutParams(dp(40), dp(35)))
        btn.setText(isRTL() and "<-" or "->")
        btn.setTextColor(UI.LOGO)
        btn.setGravity(Gravity.CENTER)
        btn.setTypeface(Typeface.create("sans-serif-black", Typeface.BOLD))
        btn.setTextSize(1, 14)
        btn.setBackground(getSkin(UI.ACCENT, 8))
        local runAction = function() safeCallback() end
        card.setOnClickListener(View.OnClickListener({ onClick = runAction }))
        btn.setOnClickListener(View.OnClickListener({ onClick = runAction }))
        actionArea.addView(btn)

    elseif mode == "ro" then
        local info = TextView(activity)
        -- Tap-to-copy affordance: a chip-style background (like every other
        -- interactive control) plus a copy glyph, so RO cards don't look like
        -- a plain inert label. The raw (un-suffixed) value is tracked in
        -- RO_RawValues so updateRO() can keep both the display and the
        -- clipboard payload in sync for fields that change at runtime.
        local rawVal = tostring(extra or T("ui.na"))
        RO_RawValues[id] = rawVal
        info.setText(_roDisplayText(rawVal) .. "  \xe2\xa7\x89")
        info.setTextColor(UI.LOGO)
        info.setTypeface(Typeface.create("sans-serif-medium", Typeface.BOLD))
        info.setTextSize(1, 11)
        info.setPadding(dp(8), dp(4), dp(8), dp(4))
        info.setBackground(getSkin(UI.MUTED, 8))
        info.setMaxWidth(dp(160))
        info.setSingleLine(true)
        info.setEllipsize(TruncateAt.END)
        info.setFocusable(true)
        info.setClickable(true)
        info.setOnClickListener(View.OnClickListener({ onClick = function(v)
            local cm = activity.getSystemService("clipboard")
            cm.setPrimaryClip(ClipData.newPlainText("Copy", tostring(RO_RawValues[id])))
        end }))
        RO_Fields[id] = info
        actionArea.addView(info)

    elseif mode == "spinner" then
        local dropdown = LinearLayout(activity)
        dropdown.setOrientation(1)
        dropdown.setVisibility(View.GONE)
        dropdown.setPadding(0, dp(5), 0, dp(5))

        local savedIdx   = spinnerStates[id]
        local defaultIdx = extra.default or 1
        local currentIdx = savedIdx or defaultIdx
        local options    = extra.options or extra
        local initialTxt = options[currentIdx] or T("ui.spinner_select")

        local val = TextView(activity)
        val.setText(tostring(initialTxt))
        val.setTextColor(UI.LOGO)
        val.setTypeface(Typeface.create("sans-serif-medium", Typeface.BOLD))
        if isRTL() then val.setGravity(Gravity.RIGHT) end
        actionArea.addView(val)

        local function buildDropdown()
            dropdown.removeAllViews()
            for i, item in ipairs(options) do
                local opt = TextView(activity)
                opt.setText(tostring(item))
                opt.setTextColor(UI.TEXT)
                opt.setPadding(dp(12), dp(10), dp(12), dp(10))
                opt.setBackground(getSkin(UI.BG, 8, 1, UI.STROKE))
                if isRTL() then opt.setGravity(Gravity.RIGHT) end
                opt.setOnClickListener(View.OnClickListener({ onClick = function()
                    val.setText(tostring(item))
                    dropdown.setVisibility(View.GONE)
                    activeSpinner = nil
                    spinnerStates[id] = i
                    safeCallback(item, i)
                end }))
                local lp = LinLayoutParams(-1, -2)
                lp.topMargin = dp(4)
                dropdown.addView(opt, lp)
            end
        end

        card.setOnClickListener(View.OnClickListener({ onClick = function()
            if processingStates[id] then return end
            if activeSpinner and activeSpinner ~= dropdown then
                activeSpinner.setVisibility(View.GONE)
            end
            if dropdown.getVisibility() == View.GONE then
                buildDropdown()
                dropdown.setVisibility(View.VISIBLE)
                activeSpinner = dropdown
            else
                dropdown.setVisibility(View.GONE)
                activeSpinner = nil
            end
        end }))
        if isRTL() then
            topRow.addView(actionArea, 0)
        else
            topRow.addView(actionArea)
        end
        card.addView(topRow)
        card.addView(dropdown)

    elseif mode == "slider" then
        local sliderContainer = LinearLayout(activity)
        sliderContainer.setOrientation(1)
        sliderContainer.setPadding(dp(5), dp(5), dp(5), dp(5))

        local isMulti    = type(extra[1]) == "table"
        local slidersData = isMulti and extra or {extra}

        if not sliderStates[id] then
            if isMulti then
                local temp = {}
                for i, cfg in ipairs(slidersData) do temp[i] = cfg.current end
                sliderStates[id] = temp
            else
                sliderStates[id] = slidersData[1].current
            end
        end

        local currentValues = isMulti and sliderStates[id] or {sliderStates[id]}

        for i, cfg in ipairs(slidersData) do
            local valTxt = TextView(activity)
            valTxt.setText((cfg.title or T("ui.slider_default_title")) .. ": " .. currentValues[i])
            valTxt.setTextColor(UI.SUB)
            valTxt.setTextSize(1, 10)
            valTxt.setPadding(dp(2), dp(5), 0, 0)
            if isRTL() then valTxt.setGravity(Gravity.RIGHT) end
            sliderContainer.addView(valTxt)

            local controlsRow = LinearLayout(activity)
            controlsRow.setOrientation(0)
            controlsRow.setGravity(Gravity.CENTER_VERTICAL)

            local isLast     = (i == #slidersData)
            local seekParams = LinLayoutParams(0, dp(35), 1.0)
            -- Reserve space matching the goBtn's width on non-last rows so all
            -- seekbars line up. The goBtn sits on the end opposite reading
            -- direction, so the reserved margin flips for RTL.
            if not isLast then
                if isRTL() then
                    seekParams.setMargins(dp(40), 0, 0, 0)
                else
                    seekParams.setMargins(0, 0, dp(40), 0)
                end
            end

            local seek = SeekBar(activity)
            seek.setLayoutParams(seekParams)
            seek.setMax(cfg.max - cfg.min)
            seek.setProgress(currentValues[i] - cfg.min)
            seek.setOnSeekBarChangeListener(SeekBar.OnSeekBarChangeListener({
                onProgressChanged = function(s, p, f)
                    local newVal = p + cfg.min
                    currentValues[i] = newVal
                    if isMulti then sliderStates[id][i] = newVal else sliderStates[id] = newVal end
                    valTxt.setText((cfg.title or T("ui.slider_default_title")) .. ": " .. newVal)
                end
            }))
            controlsRow.addView(seek)

            if isLast then
                local goBtn = TextView(activity)
                goBtn.setLayoutParams(LinLayoutParams(dp(40), dp(30)))
                goBtn.setText(isRTL() and "<-" or "->")
                goBtn.setTextColor(UI.LOGO)
                goBtn.setGravity(Gravity.CENTER)
                goBtn.setTypeface(Typeface.create("sans-serif-black", Typeface.BOLD))
                goBtn.setBackground(getSkin(UI.ACCENT, 8))
                goBtn.setOnClickListener(View.OnClickListener({
                    onClick = function() safeCallback(sliderStates[id]) end
                }))
                if isRTL() then
                    controlsRow.addView(goBtn, 0)
                else
                    controlsRow.addView(goBtn)
                end
            end
            sliderContainer.addView(controlsRow)
        end
        card.addView(sliderContainer)

    elseif mode == "input" then
        local inputs = {}

        local inputContainer = LinearLayout(activity)
        inputContainer.setOrientation(1)
        inputContainer.setLayoutParams(LinLayoutParams(-1, -2))
        inputContainer.setPadding(0, dp(8), 0, 0)

        local dataKeys = type(extra) == "table" and extra or {extra}

        if not inputStates[id] then
            if #dataKeys > 1 then
                local temp = {}
                for i, data in ipairs(dataKeys) do
                    temp[i] = type(data) == "table" and data.value or ""
                end
                inputStates[id] = temp
            else
                inputStates[id] = type(dataKeys[1]) == "table" and dataKeys[1].value or ""
            end
        end

        local function performMod()
            local results = {}
            for i, e in ipairs(inputs) do results[i] = tostring(e.getText() or "") end

            if #results == 1 then inputStates[id] = results[1]
            else                  inputStates[id] = results end

            -- Dismiss keyboard and reset window flags.
            local imm = activity.getSystemService(Context.INPUT_METHOD_SERVICE)
            if menuView then imm.hideSoftInputFromWindow(menuView.getWindowToken(), 0) end
            for _, e in ipairs(inputs) do e.clearFocus() end
            mParams.flags = 8 | 32
            windowManager.updateViewLayout(menuView, mParams)

            if #results == 1 then safeCallback(results[1])
            else                  safeCallback(results) end
        end

        for i, data in ipairs(dataKeys) do
            local row = LinearLayout(activity)
            row.setOrientation(0)
            setLayoutDir(row)
            local rp = LinLayoutParams(-1, dp(35))
            if i > 1 then rp.topMargin = dp(6) end
            row.setLayoutParams(rp)

            local edit = EditText(activity)
            local editParams = LinLayoutParams(0, -1, 1.0)
            -- Reserve space for the trailing goBtn; flips side for RTL.
            if i < #dataKeys then
                if isRTL() then
                    editParams.setMargins(dp(48), 0, 0, 0)
                else
                    editParams.setMargins(0, 0, dp(48), 0)
                end
            end
            edit.setLayoutParams(editParams)

            local h        = type(data) == "table" and data.hint or data
            local savedVal = type(inputStates[id]) == "table" and inputStates[id][i] or inputStates[id]
            local itype    = type(data) == "table" and data.type or "text"

            edit.setHint(tostring(h))
            edit.setText(tostring(savedVal))
            if Build.VERSION.SDK_INT >= 12 then edit.setTextIsSelectable(true) end

            if itype == "password" then
                edit.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD)
                edit.setTransformationMethod(PasswordTransformationMethod.getInstance())
                edit.post(Runnable({ run = function()
                    edit.setTransformationMethod(PasswordTransformationMethod.getInstance())
                end }))
            elseif itype == "number" then
                edit.setInputType(InputType.TYPE_CLASS_NUMBER | InputType.TYPE_NUMBER_FLAG_DECIMAL | InputType.TYPE_NUMBER_FLAG_SIGNED)
            elseif itype == "date" then
                edit.setInputType(InputType.TYPE_CLASS_DATETIME)
            else
                edit.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS)
            end

            local IME_FLAG_NO_EXTRACT_UI = 16777216
            local IME_FLAG_NO_FULLSCREEN = 33554432
            local IME_ACTION_DONE        = 6
            edit.setImeOptions(IME_FLAG_NO_EXTRACT_UI | IME_FLAG_NO_FULLSCREEN | IME_ACTION_DONE)

            edit.setTextColor(UI.TEXT)
            edit.setHintTextColor(UI.SUB)
            edit.setTextSize(1, 12)
            edit.setSingleLine(true)
            edit.setPadding(dp(10), 0, dp(10), 0)
            edit.setBackground(getSkin(UI.BG, 8, 1, UI.STROKE))
            if isRTL() then edit.setGravity(Gravity.RIGHT | Gravity.CENTER_VERTICAL) end

            edit.addTextChangedListener(TextWatcher{
                onTextChanged = function(s, start, before, count)
                    if type(inputStates[id]) == "table" then
                        inputStates[id][i] = tostring(s)
                    else
                        inputStates[id] = tostring(s)
                    end
                end
            })

            edit.setOnKeyListener(View.OnKeyListener{
                onKey = function(v, keyCode, event)
                    if event.getAction() == 0 then
                        if keyCode == 66 then
                            performMod(); return true
                        elseif keyCode == 61 then
                            local next = inputs[i + 1]
                            if next then next.requestFocus() else inputs[1].requestFocus() end
                            return true
                        end
                    end
                    return false
                end
            })

            edit.setOnTouchListener(View.OnTouchListener{
                onTouch = function(v, ev)
                    if ev.getAction() == MotionEvent.ACTION_DOWN then
                        mParams.flags = WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL | WindowManager.LayoutParams.FLAG_WATCH_OUTSIDE_TOUCH
                        windowManager.updateViewLayout(menuView, mParams)
                        v.requestFocus()
                        local imm = activity.getSystemService(Context.INPUT_METHOD_SERVICE)
                        v.postDelayed(function()
                            imm.showSoftInput(v, InputMethodManager.SHOW_IMPLICIT)
                        end, 80)
                    end
                    return false
                end
            })

            table.insert(inputs, edit)
            row.addView(edit)

            if i == #dataKeys then
                local goBtn = TextView(activity)
                local gbp   = LinLayoutParams(dp(40), -1)
                if isRTL() then
                    gbp.rightMargin = dp(8)
                else
                    gbp.leftMargin = dp(8)
                end
                goBtn.setLayoutParams(gbp)
                goBtn.setText(isRTL() and "<-" or "->")
                goBtn.setTextColor(UI.LOGO)
                goBtn.setGravity(Gravity.CENTER)
                goBtn.setTypeface(Typeface.create("sans-serif-black", Typeface.BOLD))
                goBtn.setBackground(getSkin(UI.ACCENT, 8))
                goBtn.setOnClickListener(View.OnClickListener{ onClick = performMod })
                if isRTL() then
                    row.addView(goBtn, 0)
                else
                    row.addView(goBtn)
                end
            end

            currentInputs = inputs
            inputContainer.addView(row)
        end
        card.addView(inputContainer)
    end

    if mode ~= "spinner" then
        -- textLayout was always added first (index 0) above. In RTL the
        -- action widget (toggle/button/info) belongs on the visual left,
        -- so it must be prepended — appending it here, as before, left it
        -- on the right in every language, which is the actual root cause
        -- of the "goBtn doesn't follow RTL" reports: switch/button/ro cards
        -- never reordered at all, only input/slider (which build their own
        -- row) did.
        if isRTL() then
            topRow.addView(actionArea, 0)
        else
            topRow.addView(actionArea)
        end
        card.addView(topRow, 0)
    end

    parent.addView(card)
end


